// === File: js/editor/coverDesigner.js ===
// js/editor/coverDesigner.js - Diseñador y renderizador de portadas para Cuadernos Digitales
class CoverDesigner {
  static TEMPLATES = {
    moleskine: {
      name: 'Moleskine Clásica',
      bg: '#0f172a',
      accent: '#3b82f6',
      textColor: '#ffffff',
      subtextColor: '#94a3b8'
    },
    leather: {
      name: 'Cuero Rústico',
      bg: '#78350f',
      accent: '#d97706',
      textColor: '#fef3c7',
      subtextColor: '#fde68a'
    },
    minimal: {
      name: 'Minimalista Blanco',
      bg: '#ffffff',
      accent: '#2563eb',
      textColor: '#0f172a',
      subtextColor: '#64748b'
    },
    pastel: {
      name: 'Tonos Pastel Menta',
      bg: '#ecfdf5',
      accent: '#10b981',
      textColor: '#064e3b',
      subtextColor: '#047857'
    },
    custom: {
      name: 'Imagen Personalizada',
      bg: '#1e293b',
      accent: '#38bdf8',
      textColor: '#ffffff',
      subtextColor: '#e2e8f0'
    }
  };

  static renderCover(ctx, width, height, coverData = {}) {
    const templateKey = coverData.template || 'moleskine';
    const tmpl = this.TEMPLATES[templateKey] || this.TEMPLATES.moleskine;
    const title = coverData.title || 'Mi Cuaderno';
    const subtitle = coverData.subtitle || 'Notas y Apuntes';
    const date = coverData.date || new Date().getFullYear().toString();
    const bgColor = coverData.color || tmpl.bg;

    ctx.save();
    ctx.clearRect(0, 0, width, height);

    // 1. Fondo base de la portada
    ctx.fillStyle = bgColor;
    ctx.fillRect(0, 0, width, height);

    // Si hay imagen personalizada de fondo
    if (coverData.customImage && coverData._imgElement && coverData._imgElement.complete) {
      ctx.drawImage(coverData._imgElement, 0, 0, width, height);
      // Capa de oscurecimiento para legibilidad
      ctx.fillStyle = 'rgba(15, 23, 42, 0.45)';
      ctx.fillRect(0, 0, width, height);
    }

    if (templateKey === 'moleskine') {
      // Banda elástica derecha
      ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
      ctx.fillRect(width - 50, 0, 24, height);

      // Lomo izquierdo
      ctx.fillStyle = 'rgba(255, 255, 255, 0.08)';
      ctx.fillRect(0, 0, 36, height);
      ctx.strokeStyle = 'rgba(0, 0, 0, 0.4)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(36, 0);
      ctx.lineTo(36, height);
      ctx.stroke();

      // Etiqueta centrada clásica
      const labelW = Math.min(width * 0.72, 480);
      const labelH = 220;
      const labelX = (width - labelW) / 2 + 10;
      const labelY = height * 0.32;

      ctx.fillStyle = '#f8fafc';
      ctx.fillRect(labelX, labelY, labelW, labelH);
      ctx.strokeStyle = '#cbd5e1';
      ctx.lineWidth = 2;
      ctx.strokeRect(labelX, labelY, labelW, labelH);

      // Marco interior
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 1;
      ctx.strokeRect(labelX + 8, labelY + 8, labelW - 16, labelH - 16);

      // Textos de la etiqueta
      ctx.textAlign = 'center';
      ctx.fillStyle = '#0f172a';
      ctx.font = 'bold 28px "Georgia", serif';
      ctx.fillText(title, labelX + labelW / 2, labelY + 70);

      ctx.font = '16px "Georgia", serif';
      ctx.fillStyle = '#475569';
      ctx.fillText(subtitle, labelX + labelW / 2, labelY + 120);

      ctx.font = 'italic 14px "Georgia", serif';
      ctx.fillStyle = '#94a3b8';
      ctx.fillText(date, labelX + labelW / 2, labelY + 165);

    } else if (templateKey === 'leather') {
      // Pespunte / costura en los bordes
      ctx.strokeStyle = '#d97706';
      ctx.lineWidth = 2;
      ctx.setLineDash([8, 6]);
      ctx.strokeRect(20, 20, width - 40, height - 40);
      ctx.setLineDash([]);

      // Marco dorado central
      const boxW = Math.min(width * 0.75, 520);
      const boxH = 240;
      const boxX = (width - boxW) / 2;
      const boxY = height * 0.3;

      ctx.strokeStyle = '#f59e0b';
      ctx.lineWidth = 3;
      ctx.strokeRect(boxX, boxY, boxW, boxH);

      ctx.textAlign = 'center';
      ctx.fillStyle = '#fef3c7';
      ctx.font = 'bold 32px "Times New Roman", serif';
      ctx.fillText(title.toUpperCase(), width / 2, boxY + 80);

      ctx.font = '18px "Times New Roman", serif';
      ctx.fillStyle = '#fde68a';
      ctx.fillText(subtitle, width / 2, boxY + 135);

      ctx.font = 'italic 15px "Times New Roman", serif';
      ctx.fillStyle = '#d97706';
      ctx.fillText(date, width / 2, boxY + 185);

    } else if (templateKey === 'minimal' || templateKey === 'pastel') {
      // Franja de acento superior
      ctx.fillStyle = tmpl.accent;
      ctx.fillRect(0, 0, width, 12);

      // Acento geométrico lateral
      ctx.fillRect(50, height * 0.28, 6, 120);

      ctx.textAlign = 'left';
      ctx.fillStyle = tmpl.textColor;
      ctx.font = 'bold 36px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
      ctx.fillText(title, 72, height * 0.33);

      ctx.fillStyle = tmpl.subtextColor;
      ctx.font = '500 20px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
      ctx.fillText(subtitle, 72, height * 0.38);

      ctx.fillStyle = '#94a3b8';
      ctx.font = '14px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
      ctx.fillText(date, 72, height * 0.44);

    } else {
      // Personalizada / Foto
      ctx.textAlign = 'center';
      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 36px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
      ctx.fillText(title, width / 2, height * 0.4);

      ctx.fillStyle = '#e2e8f0';
      ctx.font = '20px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
      ctx.fillText(subtitle, width / 2, height * 0.46);

      ctx.fillStyle = '#94a3b8';
      ctx.font = '16px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
      ctx.fillText(date, width / 2, height * 0.52);
    }

    ctx.restore();
  }

  static generateCoverThumbnail(coverData, thumbW = 280, thumbH = 390) {
    const canvas = document.createElement('canvas');
    canvas.width = thumbW;
    canvas.height = thumbH;
    const ctx = canvas.getContext('2d');
    this.renderCover(ctx, thumbW, thumbH, coverData);
    return canvas.toDataURL('image/jpeg', 0.88);
  }

  static renderPaperPreview(ctx, width, height, pattern = 'ruled', paperColor = '#ffffff') {
    ctx.save();
    ctx.fillStyle = paperColor || '#ffffff';
    ctx.fillRect(0, 0, width, height);

    const isDarkPaper = paperColor === '#1e293b' || paperColor === '#0f172a';

    if (pattern === 'ruled') {
      ctx.strokeStyle = isDarkPaper ? 'rgba(255, 255, 255, 0.2)' : '#cbd5e1';
      ctx.lineWidth = 1;
      const lineGap = Math.max(10, Math.round(height / 28));
      const topMargin = Math.round(height * 0.12);

      for (let y = topMargin; y < height; y += lineGap) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      ctx.strokeStyle = isDarkPaper ? 'rgba(248, 113, 113, 0.45)' : '#fca5a5';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      const marginX = Math.round(width * 0.1);
      ctx.moveTo(marginX, 0);
      ctx.lineTo(marginX, height);
      ctx.stroke();

    } else if (pattern === 'grid') {
      ctx.strokeStyle = isDarkPaper ? 'rgba(255, 255, 255, 0.15)' : '#e2e8f0';
      ctx.lineWidth = 1;
      const gap = Math.max(8, Math.round(width / 24));

      for (let x = 0; x <= width; x += gap) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }
      for (let y = 0; y <= height; y += gap) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

    } else if (pattern === 'dots') {
      ctx.fillStyle = isDarkPaper ? 'rgba(255, 255, 255, 0.3)' : '#94a3b8';
      const gap = Math.max(10, Math.round(width / 18));
      for (let x = gap; x < width; x += gap) {
        for (let y = gap; y < height; y += gap) {
          ctx.beginPath();
          ctx.arc(x, y, 1.25, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }

    ctx.restore();
  }
}




// === File: js/editor/canvasEngine.js ===
// js/editor/canvasEngine.js - Motor de lienzo vectorial multicapa con soporte de figuras, texto, imágenes y patrones
class CanvasEngine {
  constructor(canvasElement, options = {}) {
    this.canvas = canvasElement;
    this.ctx = this.canvas.getContext('2d');

    this.format = options.format || 'a4'; // 'a4' o 'board'
    this.backgroundPattern = this.format === 'a4' ? 'ruled' : 'dots'; // 'blank' | 'ruled' | 'grid' | 'dots'
    this.paperColor = options.paperColor || '#ffffff';

    // Colecciones de elementos por capa
    this.strokes = [];
    this.shapes = [];
    this.texts = [];
    this.images = [];

    this.undoStack = [];
    this.redoStack = [];

    // Estado del puntero y herramienta activa
    this.tool = 'pen'; // 'pen' | 'pencil' | 'marker' | 'brush' | 'highlighter' | 'eraser' | 'lasso' | 'hand' | 'shape' | 'text' | 'image'
    this.strokeColor = '#1e293b';
    this.strokeWidth = 3;
    this.strokeOpacity = 1;
    this.strokeStabilization = 0.5; // Estabilidad / Suavizado de 0 (directo) a 1 (máxima suavidad)
    this.strokeConcentration = 1.0; // Concentración / Densidad de tinta de 0.1 a 1.0 (100% sólido)
    this._stabilizedPoint = null;

    // Configuración de borrador
    this.eraserMode = 'stroke'; // 'stroke' (trazo completo) | 'area' (circular)
    this.eraseHighlighterOnly = false;
    this.eraserRadius = 16;

    // Estado de trazo activo
    this.isDrawing = false;
    this.currentStroke = null;
    this.lastPointerX = 0;
    this.lastPointerY = 0;

    // Hold-to-Straighten
    this.holdTimer = null;
    this.HOLD_DELAY_MS = 450;
    this.holdStartPoint = null;

    // Palm Rejection & Input Mode (Modo stylus con rechazo de palma por defecto)
    this.inputMode = options.inputMode || 'stylus-first'; // 'stylus-first' | 'finger-drawing'

    // Callbacks
    this.onStrokeEnd = options.onStrokeEnd || null;

    this._pointerDownHandler = null;
    this._pointerMoveHandler = null;
    window.addEventListener('pointerup', (e) => this.onPointerUp(e));
    window.addEventListener('pointercancel', (e) => this.onPointerUp(e));

    this.attachCanvas(this.canvas);
    this.initDimensions();
  }

  attachCanvas(canvasElement, pageData = null) {
    if (this.canvas && this._pointerDownHandler) {
      this.canvas.removeEventListener('pointerdown', this._pointerDownHandler);
      this.canvas.removeEventListener('pointermove', this._pointerMoveHandler);
    }

    this.canvas = canvasElement;
    this.ctx = this.canvas.getContext('2d');

    this._pointerDownHandler = (e) => this.onPointerDown(e);
    this._pointerMoveHandler = (e) => this.onPointerMove(e);
    this.canvas.addEventListener('pointerdown', this._pointerDownHandler);
    this.canvas.addEventListener('pointermove', this._pointerMoveHandler);

    if (pageData) {
      this.loadPage(pageData);
    } else {
      this.render();
    }
  }

  initDimensions() {
    const FORMATS = {
      a4: { width: 794, height: 1123 },
      board: { width: 1800, height: 1200 }
    };
    const { width, height } = FORMATS[this.format] || FORMATS.a4;
    this.canvas.width = width;
    this.canvas.height = height;
    this.render();
  }

  setFormat(formatKey) {
    this.format = formatKey;
    if (this.format === 'a4' && this.backgroundPattern === 'dots') {
      this.backgroundPattern = 'ruled';
    } else if (this.format === 'board' && this.backgroundPattern === 'ruled') {
      this.backgroundPattern = 'dots';
    }
    this.initDimensions();
  }

  setBackgroundPattern(pattern) {
    this.backgroundPattern = pattern;
    this.render();
    if (this.onStrokeEnd) this.onStrokeEnd();
  }

  setPaperColor(color) {
    this.paperColor = color;
    this.render();
    if (this.onStrokeEnd) this.onStrokeEnd();
  }

  setTool(tool) {
    this.tool = tool;
  }

  setColor(color) {
    this.strokeColor = color;
  }

  setWidth(width) {
    this.strokeWidth = Math.max(1, Number(width) || 1);
  }

  setStabilization(stabilization) {
    this.strokeStabilization = Math.max(0, Math.min(1, Number(stabilization) || 0));
  }

  setConcentration(concentration) {
    this.strokeConcentration = Math.max(0.1, Math.min(1, Number(concentration) || 0.1));
  }

  setOpacity(opacity) {
    this.strokeOpacity = Number(opacity);
  }

  setEraserMode(mode) {
    this.eraserMode = mode;
  }

  setEraseHighlighterOnly(val) {
    this.eraseHighlighterOnly = Boolean(val);
  }

  setInputMode(mode) {
    this.inputMode = mode; // 'stylus-first' | 'finger-drawing'
  }

  loadPage(page) {
    if (!page) return;
    this.isCover = Boolean(page.isCover || page.template);
    this.coverData = this.isCover ? (page.coverData || page) : null;
    this.backgroundPattern = page.backgroundPattern || (this.format === 'a4' ? 'ruled' : 'dots');
    this.paperColor = page.paperColor || '#ffffff';
    this.strokes = JSON.parse(JSON.stringify(page.strokes || []));
    this.shapes = JSON.parse(JSON.stringify(page.shapes || []));
    this.texts = JSON.parse(JSON.stringify(page.texts || []));
    this.images = JSON.parse(JSON.stringify(page.images || []));

    // Precargar elementos Image nativos para renderizado fluido
    for (const imgItem of this.images) {
      if (!imgItem._element && imgItem.dataUrl) {
        const img = new Image();
        img.src = imgItem.dataUrl;
        img.onload = () => this.render();
        imgItem._element = img;
      }
    }

    this.undoStack = [];
    this.redoStack = [];
    this.render();
  }

  getPageData() {
    // Sanitizar elementos de imagen para serialización limpia
    const cleanImages = this.images.map(img => ({
      id: img.id,
      x: img.x,
      y: img.y,
      width: img.width,
      height: img.height,
      dataUrl: img.dataUrl,
      rotation: img.rotation || 0
    }));

    const data = {
      backgroundPattern: this.backgroundPattern,
      paperColor: this.paperColor || '#ffffff',
      strokes: this.strokes,
      shapes: this.shapes,
      texts: this.texts,
      images: cleanImages
    };

    if (this.isCover && this.coverData) {
      data.isCover = true;
      data.template = this.coverData.template;
      data.title = this.coverData.title;
      data.subtitle = this.coverData.subtitle;
      data.date = this.coverData.date;
      data.color = this.coverData.color;
      data.customImage = this.coverData.customImage;
    }

    return data;
  }

  loadStrokes(strokes) {
    this.loadPage({ strokes: strokes, shapes: [], texts: [], images: [] });
  }

  getStrokes() {
    return this.strokes;
  }

  // Conversión precisa de coordenadas de puntero al espacio del canvas
  getCanvasCoordinates(e) {
    const rect = this.canvas.getBoundingClientRect();
    const scaleX = this.canvas.width / rect.width;
    const scaleY = this.canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY,
      pressure: e.pressure > 0 ? e.pressure : 0.5
    };
  }

  onPointerDown(e) {
    if (e.button !== 0 && e.pointerType === 'mouse') return;

    // Rechazo de palma activo: Si está en modo Stylus y el evento es un toque táctil, ignorar para dibujo
    if (this.inputMode === 'stylus-first' && e.pointerType === 'touch') {
      return;
    }

    // Si la herramienta activa es navegación o externa, delegar
    if (this.tool === 'lasso' || this.tool === 'hand' || this.tool === 'shape' || this.tool === 'text' || this.tool === 'image') {
      return;
    }

    this.canvas.setPointerCapture(e.pointerId);

    const pt = this.getCanvasCoordinates(e);
    this.isDrawing = true;
    this.lastPointerX = pt.x;
    this.lastPointerY = pt.y;

    if (this.tool === 'eraser') {
      this.handleEraser(pt);
      return;
    }

    // Inicializar nuevo trazo vectorial
    const isHighlighter = this.tool === 'highlighter';
    const isPencil = this.tool === 'pencil';
    const isBrush = this.tool === 'brush';
    const isMarker = this.tool === 'marker';
    
    // Modulación de grosor por presión si procede
    let initialWidth = this.strokeWidth;
    if (isHighlighter) {
      initialWidth = Math.max(16, this.strokeWidth * 3.2);
    } else if (isPencil) {
      initialWidth = Math.max(1.5, this.strokeWidth * (0.6 + pt.pressure * 0.7));
    } else if (isBrush) {
      initialWidth = Math.max(1.5, this.strokeWidth * (0.4 + pt.pressure * 1.2));
    } else {
      initialWidth = Math.max(1, this.strokeWidth * (0.7 + pt.pressure * 0.6));
    }

    this._stabilizedPoint = { x: pt.x, y: pt.y, pressure: pt.pressure };

    this.currentStroke = {
      id: 'stroke_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6),
      tool: this.tool,
      color: this.strokeColor,
      width: initialWidth,
      baseWidth: this.strokeWidth,
      opacity: isHighlighter ? 0.45 : (isPencil ? 0.85 : this.strokeOpacity),
      concentration: this.strokeConcentration !== undefined ? this.strokeConcentration : 1.0,
      stabilization: this.strokeStabilization !== undefined ? this.strokeStabilization : 0.5,
      isHighlighter: isHighlighter,
      isStraight: false,
      points: [{ ...pt }],
      roughBox: { minX: pt.x, minY: pt.y, maxX: pt.x, maxY: pt.y }
    };

    this.startHoldToStraightenTimer(pt);
    this.render();
  }

  onPointerMove(e) {
    if (!this.isDrawing) return;
    const pt = this.getCanvasCoordinates(e);

    if (this.tool === 'eraser') {
      this.handleEraser(pt);
      return;
    }

    if (!this.currentStroke) return;

    // Filtro de Estabilización en tiempo real (Streamline smoothing)
    let targetPt;
    const stab = this.strokeStabilization !== undefined ? this.strokeStabilization : 0.5;
    if (stab > 0.02 && this._stabilizedPoint) {
      const alpha = Math.max(0.10, 1 - (stab * 0.84));
      const smoothX = this._stabilizedPoint.x + (pt.x - this._stabilizedPoint.x) * alpha;
      const smoothY = this._stabilizedPoint.y + (pt.y - this._stabilizedPoint.y) * alpha;
      const smoothPressure = this._stabilizedPoint.pressure + (pt.pressure - this._stabilizedPoint.pressure) * alpha;
      this._stabilizedPoint = { x: smoothX, y: smoothY, pressure: smoothPressure };
      targetPt = { x: smoothX, y: smoothY, pressure: smoothPressure };
    } else {
      this._stabilizedPoint = { x: pt.x, y: pt.y, pressure: pt.pressure };
      targetPt = pt;
    }

    this.currentStroke.points.push(targetPt);
    const rb = this.currentStroke.roughBox;
    rb.minX = Math.min(rb.minX, targetPt.x);
    rb.minY = Math.min(rb.minY, targetPt.y);
    rb.maxX = Math.max(rb.maxX, targetPt.x);
    rb.maxY = Math.max(rb.maxY, targetPt.y);

    const distFromLast = Math.hypot(pt.x - this.lastPointerX, pt.y - this.lastPointerY);
    if (distFromLast > 4) {
      this.startHoldToStraightenTimer(pt);
    }

    this.lastPointerX = pt.x;
    this.lastPointerY = pt.y;
    this.render();
  }

  onPointerUp(e) {
    if (!this.isDrawing) return;
    this.isDrawing = false;
    this.clearHoldTimer();

    if (this.currentStroke) {
      if (this.currentStroke.points.length > 0) {
        if (this.strokeStabilization > 0.05 && this.lastPointerX && this.lastPointerY) {
          const lastPt = this.currentStroke.points[this.currentStroke.points.length - 1];
          const dist = Math.hypot(this.lastPointerX - lastPt.x, this.lastPointerY - lastPt.y);
          if (dist > 2) {
            this.currentStroke.points.push({
              x: this.lastPointerX,
              y: this.lastPointerY,
              pressure: lastPt.pressure || 0.5
            });
          }
        }
        this.pushAction({
          type: 'add_stroke',
          stroke: this.currentStroke
        });
        this.strokes.push(this.currentStroke);
      }
      this.currentStroke = null;
      this._stabilizedPoint = null;
      this.render();
      if (this.onStrokeEnd) this.onStrokeEnd();
    }
  }

  startHoldToStraightenTimer(point) {
    this.clearHoldTimer();
    this.holdStartPoint = point;

    this.holdTimer = setTimeout(() => {
      if (this.isDrawing && this.currentStroke && this.currentStroke.points.length >= 2) {
        const pStart = this.currentStroke.points[0];
        const pEnd = this.currentStroke.points[this.currentStroke.points.length - 1];
        
        this.currentStroke.isStraight = true;
        this.currentStroke.points = [pStart, pEnd];
        this.render();
      }
    }, this.HOLD_DELAY_MS);
  }

  clearHoldTimer() {
    if (this.holdTimer) {
      clearTimeout(this.holdTimer);
      this.holdTimer = null;
    }
  }

  handleEraser(pt) {
    this.eraseStrokesIntersecting(pt, this.eraserRadius);
  }

  eraseStrokesIntersecting(point, radius) {
    const remainingStrokes = [];
    const deletedStrokes = [];

    for (let i = 0; i < this.strokes.length; i++) {
      const stroke = this.strokes[i];

      if (this.eraseHighlighterOnly && !stroke.isHighlighter) {
        remainingStrokes.push(stroke);
        continue;
      }

      const rb = stroke.roughBox;
      const margin = stroke.width / 2 + radius;
      if (
        point.x < rb.minX - margin ||
        point.x > rb.maxX + margin ||
        point.y < rb.minY - margin ||
        point.y > rb.maxY + margin
      ) {
        remainingStrokes.push(stroke);
        continue;
      }

      let intersects = false;
      const pts = stroke.points;
      for (let j = 0; j < pts.length - 1; j++) {
        const dSq = this.distToSegmentSquared(point, pts[j], pts[j + 1]);
        if (dSq <= margin * margin) {
          intersects = true;
          break;
        }
      }

      if (intersects) {
        deletedStrokes.push({ stroke, index: i });
      } else {
        remainingStrokes.push(stroke);
      }
    }

    if (deletedStrokes.length > 0) {
      this.pushAction({
        type: 'delete_multiple_strokes',
        strokes: deletedStrokes
      });
      this.strokes = remainingStrokes;
      this.render();
      if (this.onStrokeEnd) this.onStrokeEnd();
    }
  }

  distToSegmentSquared(p, v, w) {
    const l2 = (v.x - w.x) ** 2 + (v.y - w.y) ** 2;
    if (l2 === 0) return (p.x - v.x) ** 2 + (p.y - v.y) ** 2;
    let t = ((p.x - v.x) * (w.x - v.x) + (p.y - v.y) * (w.y - v.y)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x))) ** 2 + (p.y - (v.y + t * (w.y - v.y))) ** 2;
  }

  // --- Adición y Manipulación de Figuras, Texto e Imágenes ---

  addShape(shape) {
    shape.id = shape.id || 'shape_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6);
    this.shapes.push(shape);
    this.pushAction({ type: 'add_shape', shape });
    this.render();
    if (this.onStrokeEnd) this.onStrokeEnd();
    return shape;
  }

  addText(textObj) {
    textObj.id = textObj.id || 'text_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6);
    this.texts.push(textObj);
    this.pushAction({ type: 'add_text', text: textObj });
    this.render();
    if (this.onStrokeEnd) this.onStrokeEnd();
    return textObj;
  }

  addImage(imageObj) {
    imageObj.id = imageObj.id || 'img_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6);
    
    if (!imageObj._element && imageObj.dataUrl) {
      const img = new Image();
      img.src = imageObj.dataUrl;
      img.onload = () => this.render();
      imageObj._element = img;
    }

    this.images.push(imageObj);
    this.pushAction({ type: 'add_image', image: imageObj });
    this.render();
    if (this.onStrokeEnd) this.onStrokeEnd();
    return imageObj;
  }

  // --- Deshacer / Rehacer ---
  pushAction(action) {
    this.undoStack.push(action);
    this.redoStack = [];
  }

  undo() {
    if (this.undoStack.length === 0) return false;
    const action = this.undoStack.pop();

    if (action.type === 'add_stroke') {
      const idx = this.strokes.findIndex(s => s.id === action.stroke.id);
      if (idx !== -1) this.strokes.splice(idx, 1);
      this.redoStack.push(action);
    } else if (action.type === 'delete_multiple_strokes') {
      for (const item of action.strokes) {
        this.strokes.splice(item.index, 0, item.stroke);
      }
      this.redoStack.push(action);
    } else if (action.type === 'add_shape') {
      const idx = this.shapes.findIndex(sh => sh.id === action.shape.id);
      if (idx !== -1) this.shapes.splice(idx, 1);
      this.redoStack.push(action);
    } else if (action.type === 'add_text') {
      const idx = this.texts.findIndex(t => t.id === action.text.id);
      if (idx !== -1) this.texts.splice(idx, 1);
      this.redoStack.push(action);
    } else if (action.type === 'add_image') {
      const idx = this.images.findIndex(im => im.id === action.image.id);
      if (idx !== -1) this.images.splice(idx, 1);
      this.redoStack.push(action);
    }

    this.render();
    if (this.onStrokeEnd) this.onStrokeEnd();
    return true;
  }

  redo() {
    if (this.redoStack.length === 0) return false;
    const action = this.redoStack.pop();

    if (action.type === 'add_stroke') {
      this.strokes.push(action.stroke);
      this.undoStack.push(action);
    } else if (action.type === 'delete_multiple_strokes') {
      const idsToDelete = new Set(action.strokes.map(s => s.stroke.id));
      this.strokes = this.strokes.filter(s => !idsToDelete.has(s.id));
      this.undoStack.push(action);
    } else if (action.type === 'add_shape') {
      this.shapes.push(action.shape);
      this.undoStack.push(action);
    } else if (action.type === 'add_text') {
      this.texts.push(action.text);
      this.undoStack.push(action);
    } else if (action.type === 'add_image') {
      this.images.push(action.image);
      this.undoStack.push(action);
    }

    this.render();
    if (this.onStrokeEnd) this.onStrokeEnd();
    return true;
  }

  clearAll() {
    if (this.strokes.length === 0 && this.shapes.length === 0 && this.texts.length === 0 && this.images.length === 0) return;
    this.strokes = [];
    this.shapes = [];
    this.texts = [];
    this.images = [];
    this.render();
    if (this.onStrokeEnd) this.onStrokeEnd();
  }

  // --- Renderizado Multicapa ---
  render() {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

    // 1. Capa 0: Fondo de Hoja (Blanco, Rayado, Cuadrícula 5mm, Puntos)
    this.renderBackground(ctx);

    // 2. Capa 1: Imágenes incrustadas
    this.renderImages(ctx);

    // 3. Capa 2: Subrayadores (con modo de fusión multiply, por debajo de la tinta)
    ctx.save();
    ctx.globalCompositeOperation = 'multiply';
    for (const stroke of this.strokes) {
      if (stroke.isHighlighter) {
        this.drawStroke(ctx, stroke);
      }
    }
    if (this.currentStroke && this.currentStroke.isHighlighter) {
      this.drawStroke(ctx, this.currentStroke);
    }
    ctx.restore();

    // 4. Capa 3: Figuras Geométricas y Tinta (Lápiz, Rotulador, Pincel)
    ctx.save();
    ctx.globalCompositeOperation = 'source-over';

    // Renderizar figuras
    for (const shape of this.shapes) {
      this.drawShape(ctx, shape);
    }

    // Renderizar trazos de tinta
    for (const stroke of this.strokes) {
      if (!stroke.isHighlighter) {
        this.drawStroke(ctx, stroke);
      }
    }
    if (this.currentStroke && !this.currentStroke.isHighlighter) {
      this.drawStroke(ctx, this.currentStroke);
    }
    ctx.restore();

    // 5. Capa 4: Cajas de Texto
    ctx.save();
    for (const textObj of this.texts) {
      this.drawText(ctx, textObj);
    }
    ctx.restore();
  }

  renderBackground(ctx) {
    ctx.save();
    if (this.isCover && this.coverData) {
      CoverDesigner.renderCover(ctx, this.canvas.width, this.canvas.height, this.coverData);
      ctx.restore();
      return;
    }

    const bgColor = this.paperColor || '#ffffff';
    ctx.fillStyle = bgColor;
    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

    const pattern = this.backgroundPattern || (this.format === 'a4' ? 'ruled' : 'dots');
    const isDarkPaper = bgColor === '#1e293b' || bgColor === '#0f172a';

    if (pattern === 'ruled') {
      // Pauta rayada horizontal continua
      ctx.strokeStyle = isDarkPaper ? 'rgba(255, 255, 255, 0.2)' : '#cbd5e1';
      ctx.lineWidth = 1;
      const lineGap = 32;
      const topMargin = 75;

      for (let y = topMargin; y < this.canvas.height; y += lineGap) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(this.canvas.width, y);
        ctx.stroke();
      }

      // Margen izquierdo rojo estilo cuaderno escolar
      ctx.strokeStyle = isDarkPaper ? 'rgba(248, 113, 113, 0.45)' : '#fca5a5';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(68, 0);
      ctx.lineTo(68, this.canvas.height);
      ctx.stroke();

    } else if (pattern === 'grid') {
      // Cuadrícula técnica de 5 mm (~20 px) que cubre el 100% de la superficie
      ctx.strokeStyle = isDarkPaper ? 'rgba(255, 255, 255, 0.15)' : '#e2e8f0';
      ctx.lineWidth = 1;
      const gap = 20;

      for (let x = 0; x <= this.canvas.width; x += gap) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, this.canvas.height);
        ctx.stroke();
      }

      for (let y = 0; y <= this.canvas.height; y += gap) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(this.canvas.width, y);
        ctx.stroke();
      }

    } else if (pattern === 'dots') {
      // Trama de puntos (Bullet journal / Pizarra)
      ctx.fillStyle = isDarkPaper ? 'rgba(255, 255, 255, 0.25)' : '#94a3b8';
      const gap = 24;
      for (let x = gap; x < this.canvas.width; x += gap) {
        for (let y = gap; y < this.canvas.height; y += gap) {
          ctx.beginPath();
          ctx.arc(x, y, 1.25, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
    // pattern === 'blank': liso sin marcas
    ctx.restore();
  }

  renderImages(ctx) {
    for (const imgItem of this.images) {
      if (imgItem._element && imgItem._element.complete) {
        ctx.save();
        ctx.translate(imgItem.x + imgItem.width / 2, imgItem.y + imgItem.height / 2);
        if (imgItem.rotation) ctx.rotate(imgItem.rotation);
        ctx.drawImage(imgItem._element, -imgItem.width / 2, -imgItem.height / 2, imgItem.width, imgItem.height);
        ctx.restore();
      }
    }
  }

  drawShape(ctx, shape) {
    ctx.save();
    ctx.strokeStyle = shape.strokeColor || '#1e293b';
    ctx.lineWidth = shape.strokeWidth || 2;
    ctx.fillStyle = shape.fillColor || 'transparent';

    if (shape.type === 'rectangle') {
      ctx.beginPath();
      ctx.rect(shape.x, shape.y, shape.width, shape.height);
      if (shape.fillColor && shape.fillColor !== 'transparent') ctx.fill();
      ctx.stroke();

    } else if (shape.type === 'circle') {
      ctx.beginPath();
      const radiusX = Math.abs(shape.width) / 2;
      const radiusY = Math.abs(shape.height) / 2;
      const centerX = shape.x + shape.width / 2;
      const centerY = shape.y + shape.height / 2;
      ctx.ellipse(centerX, centerY, radiusX, radiusY, 0, 0, Math.PI * 2);
      if (shape.fillColor && shape.fillColor !== 'transparent') ctx.fill();
      ctx.stroke();

    } else if (shape.type === 'line') {
      ctx.beginPath();
      ctx.moveTo(shape.x, shape.y);
      ctx.lineTo(shape.x + shape.width, shape.y + shape.height);
      ctx.stroke();

    } else if (shape.type === 'arrow') {
      const fromX = shape.x;
      const fromY = shape.y;
      const toX = shape.x + shape.width;
      const toY = shape.y + shape.height;

      const headLen = Math.min(24, Math.max(12, shape.strokeWidth * 4));
      const angle = Math.atan2(toY - fromY, toX - fromX);

      // Línea principal
      ctx.beginPath();
      ctx.moveTo(fromX, fromY);
      ctx.lineTo(toX, toY);
      ctx.stroke();

      // Punta de flecha
      ctx.beginPath();
      ctx.moveTo(toX, toY);
      ctx.lineTo(toX - headLen * Math.cos(angle - Math.PI / 6), toY - headLen * Math.sin(angle - Math.PI / 6));
      ctx.moveTo(toX, toY);
      ctx.lineTo(toX - headLen * Math.cos(angle + Math.PI / 6), toY - headLen * Math.sin(angle + Math.PI / 6));
      ctx.stroke();
    }

    ctx.restore();
  }

  drawText(ctx, textObj) {
    ctx.save();
    ctx.font = `${textObj.fontSize || 16}px ${textObj.fontFamily || 'sans-serif'}`;
    ctx.fillStyle = textObj.color || '#1e293b';
    ctx.textBaseline = 'top';

    const lines = String(textObj.text || '').split('\n');
    const lineHeight = (textObj.fontSize || 16) * 1.35;

    for (let i = 0; i < lines.length; i++) {
      ctx.fillText(lines[i], textObj.x, textObj.y + i * lineHeight);
    }
    ctx.restore();
  }

  drawStroke(ctx, stroke) {
    const pts = stroke.points;
    if (!pts || pts.length === 0) return;

    ctx.save();
    ctx.strokeStyle = stroke.color;
    ctx.lineWidth = stroke.width;
    
    const concentration = stroke.concentration !== undefined ? stroke.concentration : 1.0;
    const baseOpacity = stroke.opacity !== undefined ? stroke.opacity : 1.0;
    ctx.globalAlpha = Math.max(0.05, Math.min(1.0, baseOpacity * concentration));
    
    ctx.lineCap = stroke.isHighlighter ? 'square' : 'round';
    ctx.lineJoin = 'round';

    if (pts.length === 1) {
      ctx.beginPath();
      ctx.arc(pts[0].x, pts[0].y, stroke.width / 2, 0, Math.PI * 2);
      ctx.fillStyle = stroke.color;
      ctx.fill();
      ctx.restore();
      return;
    }

    if (stroke.isStraight || pts.length === 2) {
      ctx.beginPath();
      ctx.moveTo(pts[0].x, pts[0].y);
      ctx.lineTo(pts[pts.length - 1].x, pts[pts.length - 1].y);
      ctx.stroke();
      ctx.restore();
      return;
    }

    // Curvas Bézier continuas suavizadas
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y);

    for (let i = 1; i < pts.length - 1; i++) {
      const midX = (pts[i].x + pts[i + 1].x) / 2;
      const midY = (pts[i].y + pts[i + 1].y) / 2;
      ctx.quadraticCurveTo(pts[i].x, pts[i].y, midX, midY);
    }

    ctx.lineTo(pts[pts.length - 1].x, pts[pts.length - 1].y);
    ctx.stroke();
    ctx.restore();
  }

  // Cálculo del Bounding Box exacto para exportación recortada en Pizarras
  getBoundingBox() {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    let hasContent = false;

    // 1. Trazos
    for (const stroke of this.strokes) {
      if (stroke.roughBox) {
        hasContent = true;
        minX = Math.min(minX, stroke.roughBox.minX - stroke.width);
        minY = Math.min(minY, stroke.roughBox.minY - stroke.width);
        maxX = Math.max(maxX, stroke.roughBox.maxX + stroke.width);
        maxY = Math.max(maxY, stroke.roughBox.maxY + stroke.width);
      }
    }

    // 2. Figuras
    for (const sh of this.shapes) {
      hasContent = true;
      const x2 = sh.x + sh.width;
      const y2 = sh.y + sh.height;
      minX = Math.min(minX, Math.min(sh.x, x2));
      minY = Math.min(minY, Math.min(sh.y, y2));
      maxX = Math.max(maxX, Math.max(sh.x, x2));
      maxY = Math.max(maxY, Math.max(sh.y, y2));
    }

    // 3. Textos
    for (const tx of this.texts) {
      hasContent = true;
      minX = Math.min(minX, tx.x);
      minY = Math.min(minY, tx.y);
      maxX = Math.max(maxX, tx.x + (tx.width || 200));
      maxY = Math.max(maxY, tx.y + (tx.fontSize || 20) * 2);
    }

    // 4. Imágenes
    for (const img of this.images) {
      hasContent = true;
      minX = Math.min(minX, img.x);
      minY = Math.min(minY, img.y);
      maxX = Math.max(maxX, img.x + img.width);
      maxY = Math.max(maxY, img.y + img.height);
    }

    if (!hasContent) {
      return { minX: 0, minY: 0, maxX: this.canvas.width, maxY: this.canvas.height, width: this.canvas.width, height: this.canvas.height };
    }

    // Margen de cortesía de 40 px
    const padding = 40;
    const cropMinX = Math.max(0, Math.floor(minX - padding));
    const cropMinY = Math.max(0, Math.floor(minY - padding));
    const cropMaxX = Math.min(this.canvas.width, Math.ceil(maxX + padding));
    const cropMaxY = Math.min(this.canvas.height, Math.ceil(maxY + padding));

    return {
      minX: cropMinX,
      minY: cropMinY,
      maxX: cropMaxX,
      maxY: cropMaxY,
      width: Math.max(100, cropMaxX - cropMinX),
      height: Math.max(100, cropMaxY - cropMinY)
    };
  }

  // Miniatura visual para tarjetas y carrusel de páginas
  generateThumbnail(thumbWidth = 280, thumbHeight = 190) {
    const thumbCanvas = document.createElement('canvas');
    thumbCanvas.width = thumbWidth;
    thumbCanvas.height = thumbHeight;
    const tCtx = thumbCanvas.getContext('2d');

    tCtx.fillStyle = '#ffffff';
    tCtx.fillRect(0, 0, thumbWidth, thumbHeight);

    const scale = Math.min(thumbWidth / this.canvas.width, thumbHeight / this.canvas.height);
    const offsetX = (thumbWidth - this.canvas.width * scale) / 2;
    const offsetY = (thumbHeight - this.canvas.height * scale) / 2;

    tCtx.save();
    tCtx.translate(offsetX, offsetY);
    tCtx.scale(scale, scale);

    this.renderBackground(tCtx);
    this.renderImages(tCtx);

    tCtx.globalCompositeOperation = 'multiply';
    for (const stroke of this.strokes) {
      if (stroke.isHighlighter) this.drawStroke(tCtx, stroke);
    }

    tCtx.globalCompositeOperation = 'source-over';
    for (const shape of this.shapes) this.drawShape(tCtx, shape);
    for (const stroke of this.strokes) {
      if (!stroke.isHighlighter) this.drawStroke(tCtx, stroke);
    }
    for (const text of this.texts) this.drawText(tCtx, text);

    tCtx.restore();
    return thumbCanvas.toDataURL('image/jpeg', 0.85);
  }

  // Renderizar los datos de una página específica en cualquier elemento canvas
  renderPageToCanvas(canvasEl, pageData) {
    if (!canvasEl || !pageData) return;
    const ctx = canvasEl.getContext('2d');
    ctx.save();

    // 1. Fondo (Portada o Patrón de Hoja)
    if (pageData.isCover || pageData.template) {
      CoverDesigner.renderCover(ctx, canvasEl.width, canvasEl.height, pageData.coverData || pageData);
    } else {
      const bgColor = pageData.paperColor || '#ffffff';
      ctx.fillStyle = bgColor;
      ctx.fillRect(0, 0, canvasEl.width, canvasEl.height);

      const pattern = pageData.backgroundPattern || (this.format === 'a4' ? 'ruled' : 'dots');
      const isDarkPaper = bgColor === '#1e293b' || bgColor === '#0f172a';

      if (pattern === 'ruled') {
        ctx.strokeStyle = isDarkPaper ? 'rgba(255, 255, 255, 0.2)' : '#cbd5e1';
        ctx.lineWidth = 1;
        const lineGap = 32;
        const topMargin = 75;
        for (let y = topMargin; y < canvasEl.height; y += lineGap) {
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(canvasEl.width, y);
          ctx.stroke();
        }
        ctx.strokeStyle = isDarkPaper ? 'rgba(248, 113, 113, 0.45)' : '#fca5a5';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(68, 0);
        ctx.lineTo(68, canvasEl.height);
        ctx.stroke();
      } else if (pattern === 'grid') {
        ctx.strokeStyle = isDarkPaper ? 'rgba(255, 255, 255, 0.15)' : '#e2e8f0';
        ctx.lineWidth = 1;
        const gap = 20;
        for (let x = 0; x <= canvasEl.width; x += gap) {
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.lineTo(x, canvasEl.height);
          ctx.stroke();
        }
        for (let y = 0; y <= canvasEl.height; y += gap) {
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(canvasEl.width, y);
          ctx.stroke();
        }
      } else if (pattern === 'dots') {
        ctx.fillStyle = isDarkPaper ? 'rgba(255, 255, 255, 0.25)' : '#94a3b8';
        const gap = 24;
        for (let x = gap; x < canvasEl.width; x += gap) {
          for (let y = 0; y < canvasEl.height; y += gap) {
            ctx.beginPath();
            ctx.arc(x, y, 1.25, 0, Math.PI * 2);
            ctx.fill();
          }
        }
      }
    }

    // 2. Imágenes
    for (const imgItem of (pageData.images || [])) {
      if (imgItem._element && imgItem._element.complete) {
        ctx.save();
        ctx.translate(imgItem.x + imgItem.width / 2, imgItem.y + imgItem.height / 2);
        if (imgItem.rotation) ctx.rotate(imgItem.rotation);
        ctx.drawImage(imgItem._element, -imgItem.width / 2, -imgItem.height / 2, imgItem.width, imgItem.height);
        ctx.restore();
      }
    }

    // 3. Subrayadores
    ctx.globalCompositeOperation = 'multiply';
    for (const stroke of (pageData.strokes || [])) {
      if (stroke.isHighlighter) this.drawStroke(ctx, stroke);
    }

    // 4. Figuras y Trazos normales
    ctx.globalCompositeOperation = 'source-over';
    for (const shape of (pageData.shapes || [])) {
      this.drawShape(ctx, shape);
    }
    for (const stroke of (pageData.strokes || [])) {
      if (!stroke.isHighlighter) this.drawStroke(ctx, stroke);
    }

    // 5. Textos
    for (const text of (pageData.texts || [])) {
      this.drawText(ctx, text);
    }

    ctx.restore();
  }
}


// === File: js/editor/shapeTool.js ===
// js/editor/shapeTool.js - Herramienta para trazar figuras geométricas interactivas
class ShapeTool {
  constructor(canvasEngine, containerEl) {
    this.engine = canvasEngine;
    this.canvas = canvasEngine.canvas;
    this.container = containerEl;

    this.shapeType = 'rectangle'; // 'rectangle' | 'circle' | 'line' | 'arrow'
    this.strokeColor = '#1e293b';
    this.strokeWidth = 3;
    this.fillColor = 'transparent'; // 'transparent' | hex | rgba

    this.isDrawingShape = false;
    this.startX = 0;
    this.startY = 0;

    this.overlayCanvas = null;
    this.overlayCtx = null;

    this.initOverlay();
    this.bindEvents();
  }

  initOverlay() {
    this.overlayCanvas = document.createElement('canvas');
    this.overlayCanvas.className = 'shape-overlay-canvas';
    this.overlayCanvas.style.position = 'absolute';
    this.overlayCanvas.style.top = '0';
    this.overlayCanvas.style.left = '0';
    this.overlayCanvas.style.width = '100%';
    this.overlayCanvas.style.height = '100%';
    this.overlayCanvas.style.pointerEvents = 'none';
    this.overlayCanvas.style.zIndex = '8';
    this.overlayCanvas.width = this.canvas.width;
    this.overlayCanvas.height = this.canvas.height;
    this.overlayCtx = this.overlayCanvas.getContext('2d');

    this.container.appendChild(this.overlayCanvas);
  }

  syncDimensions() {
    if (this.overlayCanvas) {
      this.overlayCanvas.width = this.canvas.width;
      this.overlayCanvas.height = this.canvas.height;
    }
  }

  setHost(canvasEl, hostContainer) {
    if (this.canvas && this._pointerDownHandler) {
      this.canvas.removeEventListener('pointerdown', this._pointerDownHandler);
    }
    this.canvas = canvasEl;
    this.container = hostContainer;
    if (this.overlayCanvas) {
      hostContainer.appendChild(this.overlayCanvas);
      this.syncDimensions();
    }
    this._pointerDownHandler = (e) => {
      if (this.engine.tool !== 'shape') return;
      if (e.button !== 0 && e.pointerType === 'mouse') return;
      if (this.engine.inputMode === 'stylus-first' && e.pointerType === 'touch') return;

      const pt = this.engine.getCanvasCoordinates(e);
      this.isDrawingShape = true;
      this.startX = pt.x;
      this.startY = pt.y;
    };
    this.canvas.addEventListener('pointerdown', this._pointerDownHandler);
  }

  setShapeType(type) {
    this.shapeType = type;
  }

  setStrokeColor(color) {
    this.strokeColor = color;
  }

  setStrokeWidth(w) {
    this.strokeWidth = Number(w);
  }

  setFillColor(color) {
    this.fillColor = color;
  }

  bindEvents() {
    this._pointerDownHandler = (e) => {
      if (this.engine.tool !== 'shape') return;
      if (e.button !== 0 && e.pointerType === 'mouse') return;
      if (this.engine.inputMode === 'stylus-first' && e.pointerType === 'touch') return;

      const pt = this.engine.getCanvasCoordinates(e);
      this.isDrawingShape = true;
      this.startX = pt.x;
      this.startY = pt.y;
    };
    this.canvas.addEventListener('pointerdown', this._pointerDownHandler);

    window.addEventListener('pointermove', (e) => {
      if (!this.isDrawingShape || this.engine.tool !== 'shape') return;
      const pt = this.engine.getCanvasCoordinates(e);
      this.renderPreview(pt.x, pt.y);
    });

    window.addEventListener('pointerup', (e) => {
      if (!this.isDrawingShape || this.engine.tool !== 'shape') return;
      this.isDrawingShape = false;
      const pt = this.engine.getCanvasCoordinates(e);

      // Limpiar previsualización
      this.clearOverlay();

      const width = pt.x - this.startX;
      const height = pt.y - this.startY;

      // Evitar registrar figuras accidentales sin arrastre
      if (Math.hypot(width, height) < 6) return;

      let x = this.startX;
      let y = this.startY;
      let w = width;
      let h = height;

      if (this.shapeType === 'rectangle' || this.shapeType === 'circle') {
        if (w < 0) {
          x += w;
          w = Math.abs(w);
        }
        if (h < 0) {
          y += h;
          h = Math.abs(h);
        }
      }

      this.engine.addShape({
        type: this.shapeType,
        x: x,
        y: y,
        width: w,
        height: h,
        strokeColor: this.strokeColor,
        strokeWidth: this.strokeWidth,
        fillColor: this.fillColor
      });
    });
  }

  renderPreview(currentX, currentY) {
    const ctx = this.overlayCtx;
    ctx.clearRect(0, 0, this.overlayCanvas.width, this.overlayCanvas.height);

    let x = this.startX;
    let y = this.startY;
    let w = currentX - this.startX;
    let h = currentY - this.startY;

    const tempShape = {
      type: this.shapeType,
      x: x,
      y: y,
      width: w,
      height: h,
      strokeColor: this.strokeColor,
      strokeWidth: this.strokeWidth,
      fillColor: this.fillColor
    };

    if (this.shapeType === 'rectangle' || this.shapeType === 'circle') {
      if (w < 0) {
        tempShape.x += w;
        tempShape.width = Math.abs(w);
      }
      if (h < 0) {
        tempShape.y += h;
        tempShape.height = Math.abs(h);
      }
    }

    this.engine.drawShape(ctx, tempShape);
  }

  clearOverlay() {
    this.overlayCtx.clearRect(0, 0, this.overlayCanvas.width, this.overlayCanvas.height);
  }
}


// === File: js/editor/textTool.js ===
// js/editor/textTool.js - Herramienta para crear y editar cajas de texto sobre el lienzo
class TextTool {
  constructor(canvasEngine, containerEl) {
    this.engine = canvasEngine;
    this.canvas = canvasEngine.canvas;
    this.container = containerEl;

    this.fontSize = 20;
    this.fontFamily = 'Arial, sans-serif';
    this.color = '#1e293b';

    this.activeInput = null;
    this.bindEvents();
  }

  setFontSize(size) {
    this.fontSize = Number(size);
  }

  setFontFamily(family) {
    this.fontFamily = family;
  }

  setColor(color) {
    this.color = color;
  }

  bindEvents() {
    this._clickHandler = (e) => {
      if (this.engine.tool !== 'text') return;
      if (this.activeInput) return; // Si ya hay uno abierto, dejar que se complete

      const pt = this.engine.getCanvasCoordinates(e);
      this.spawnInput(pt.x, pt.y);
    };
    this.canvas.addEventListener('click', this._clickHandler);
  }

  setHost(canvasEl, hostContainer) {
    if (this.canvas && this._clickHandler) {
      this.canvas.removeEventListener('click', this._clickHandler);
    }
    this.canvas = canvasEl;
    this.container = hostContainer;
    this._clickHandler = (e) => {
      if (this.engine.tool !== 'text') return;
      if (this.activeInput) return;

      const pt = this.engine.getCanvasCoordinates(e);
      this.spawnInput(pt.x, pt.y);
    };
    this.canvas.addEventListener('click', this._clickHandler);
  }

  spawnInput(canvasX, canvasY) {
    const textarea = document.createElement('textarea');
    textarea.className = 'canvas-text-editor';
    textarea.style.position = 'absolute';
    textarea.style.left = `${canvasX}px`;
    textarea.style.top = `${canvasY}px`;
    textarea.style.fontSize = `${this.fontSize}px`;
    textarea.style.fontFamily = this.fontFamily;
    textarea.style.color = this.color;
    textarea.placeholder = 'Escribe aquí...';
    textarea.rows = 1;

    this.container.appendChild(textarea);
    this.activeInput = textarea;

    setTimeout(() => {
      textarea.focus();
    }, 50);

    const commit = () => {
      if (!this.activeInput) return;
      const text = textarea.value.trim();
      this.container.removeChild(textarea);
      this.activeInput = null;

      if (text) {
        this.engine.addText({
          x: canvasX,
          y: canvasY,
          text: text,
          fontSize: this.fontSize,
          fontFamily: this.fontFamily,
          color: this.color
        });
      }
    };

    textarea.addEventListener('blur', commit);
    textarea.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        this.container.removeChild(textarea);
        this.activeInput = null;
      } else if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
        commit();
      }
    });
  }
}



// === File: js/editor/imageTool.js ===
// js/editor/imageTool.js - Importación y manipulación de imágenes locales sobre el lienzo
class ImageTool {
  constructor(canvasEngine, containerEl) {
    this.engine = canvasEngine;
    this.canvas = canvasEngine.canvas;
    this.container = containerEl;

    this.fileInput = null;
    this.initFileInput();
  }

  setHost(canvasEl, hostContainer) {
    this.canvas = canvasEl;
    this.container = hostContainer;
  }

  initFileInput() {
    this.fileInput = document.createElement('input');
    this.fileInput.type = 'file';
    this.fileInput.accept = 'image/png, image/jpeg, image/webp, image/svg+xml';
    this.fileInput.style.display = 'none';
    document.body.appendChild(this.fileInput);

    this.fileInput.addEventListener('change', (e) => {
      const file = e.target.files && e.target.files[0];
      if (file) {
        this.processImageFile(file);
      }
      this.fileInput.value = '';
    });
  }

  triggerUpload() {
    if (this.fileInput) {
      this.fileInput.click();
    }
  }

  processImageFile(file) {
    const reader = new FileReader();
    reader.onload = (event) => {
      const dataUrl = event.target.result;
      const img = new Image();
      img.onload = () => {
        // Calcular tamaño inicial ajustado al lienzo
        const maxInitialDim = Math.min(this.canvas.width * 0.5, 450);
        let w = img.naturalWidth;
        let h = img.naturalHeight;

        if (w > maxInitialDim || h > maxInitialDim) {
          const ratio = Math.min(maxInitialDim / w, maxInitialDim / h);
          w = Math.round(w * ratio);
          h = Math.round(h * ratio);
        }

        // Posicionar en el centro del lienzo
        const posX = Math.round((this.canvas.width - w) / 2);
        const posY = Math.round((this.canvas.height - h) / 2);

        this.engine.addImage({
          x: posX,
          y: posY,
          width: w,
          height: h,
          dataUrl: dataUrl,
          rotation: 0,
          _element: img
        });
      };
      img.src = dataUrl;
    };
    reader.readAsDataURL(file);
  }
}



// === File: js/editor/selectionTool.js ===
// js/editor/selectionTool.js - Herramienta de lazo y barra flotante de selección
class SelectionTool {
  constructor(canvasEngine, containerElement) {
    this.engine = canvasEngine;
    this.canvas = canvasEngine.canvas;
    this.container = containerElement;

    this.isActive = false;
    this.isSelecting = false;
    this.isDraggingSelection = false;

    this.lassoPoints = [];
    this.selectedStrokes = [];
    this.selectionBBox = null;

    this.dragStartX = 0;
    this.dragStartY = 0;

    this.floatingBar = null;
    this.overlayCanvas = null;
    this.overlayCtx = null;

    this.createOverlay();
    this.createFloatingBar();
    this.bindEvents();
  }

  createOverlay() {
    this.overlayCanvas = document.createElement('canvas');
    this.overlayCanvas.className = 'selection-overlay-canvas';
    this.overlayCanvas.style.position = 'absolute';
    this.overlayCanvas.style.top = '0';
    this.overlayCanvas.style.left = '0';
    this.overlayCanvas.style.width = '100%';
    this.overlayCanvas.style.height = '100%';
    this.overlayCanvas.style.pointerEvents = 'none';
    this.overlayCanvas.style.zIndex = '5';
    this.overlayCanvas.width = this.canvas.width;
    this.overlayCanvas.height = this.canvas.height;
    this.overlayCtx = this.overlayCanvas.getContext('2d');

    this.canvas.parentElement.style.position = 'relative';
    this.canvas.parentElement.appendChild(this.overlayCanvas);
  }

  createFloatingBar() {
    this.floatingBar = document.createElement('div');
    this.floatingBar.className = 'floating-selection-bar hidden';
    this.floatingBar.innerHTML = `
      <div class="selection-actions">
        <button class="sel-btn" id="btnSelDuplicate" title="Duplicar selección">${Icons.copy} <span>Duplicar</span></button>
        <button class="sel-btn" id="btnSelDelete" title="Eliminar selección">${Icons.trash} <span>Borrar</span></button>
        <div class="sel-colors">
          <button class="color-dot" data-color="#1e293b" style="background:#1e293b"></button>
          <button class="color-dot" data-color="#2563eb" style="background:#2563eb"></button>
          <button class="color-dot" data-color="#dc2626" style="background:#dc2626"></button>
          <button class="color-dot" data-color="#16a34a" style="background:#16a34a"></button>
        </div>
      </div>
    `;
    this.canvas.parentElement.appendChild(this.floatingBar);

    this.floatingBar.querySelector('#btnSelDuplicate').addEventListener('click', (e) => {
      e.stopPropagation();
      this.duplicateSelection();
    });

    this.floatingBar.querySelector('#btnSelDelete').addEventListener('click', (e) => {
      e.stopPropagation();
      this.deleteSelection();
    });

    this.floatingBar.querySelectorAll('.color-dot').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        this.changeSelectionColor(btn.dataset.color);
      });
    });
  }

  bindEvents() {
    this._pointerDownHandler = (e) => this.onPointerDown(e);
    this.canvas.addEventListener('pointerdown', this._pointerDownHandler);
    window.addEventListener('pointermove', (e) => this.onPointerMove(e));
    window.addEventListener('pointerup', (e) => this.onPointerUp(e));

    // Deseleccionar al hacer clic fuera
    document.addEventListener('click', (e) => {
      if (!this.isActive) return;
      if (!this.canvas.contains(e.target) && !this.floatingBar.contains(e.target)) {
        this.clearSelection();
      }
    });
  }

  setHost(canvasEl, hostContainer) {
    if (this.canvas && this._pointerDownHandler) {
      this.canvas.removeEventListener('pointerdown', this._pointerDownHandler);
    }
    this.canvas = canvasEl;
    this.container = hostContainer;
    if (this.overlayCanvas) {
      hostContainer.appendChild(this.overlayCanvas);
      this.syncDimensions();
    }
    if (this.floatingBar) {
      hostContainer.appendChild(this.floatingBar);
    }
    this._pointerDownHandler = (e) => this.onPointerDown(e);
    this.canvas.addEventListener('pointerdown', this._pointerDownHandler);
  }

  setActive(active) {
    this.isActive = active;
    if (!active) {
      this.clearSelection();
    }
  }

  syncDimensions() {
    if (this.overlayCanvas) {
      this.overlayCanvas.width = this.canvas.width;
      this.overlayCanvas.height = this.canvas.height;
    }
  }

  onPointerDown(e) {
    if (!this.isActive) return;
    const pt = this.engine.getCanvasCoordinates(e);

    // Si pulsamos dentro del Bounding Box existente, iniciamos arrastre de la selección
    if (this.selectedStrokes.length > 0 && this.isPointInBBox(pt, this.selectionBBox)) {
      this.isDraggingSelection = true;
      this.dragStartX = pt.x;
      this.dragStartY = pt.y;
      return;
    }

    // De lo contrario, iniciamos un nuevo trazo de lazo
    this.clearSelection();
    this.isSelecting = true;
    this.lassoPoints = [pt];
    this.renderLasso();
  }

  onPointerMove(e) {
    if (!this.isActive) return;
    const pt = this.engine.getCanvasCoordinates(e);

    if (this.isDraggingSelection) {
      const dx = pt.x - this.dragStartX;
      const dy = pt.y - this.dragStartY;

      // Mover los trazos seleccionados
      for (const stroke of this.selectedStrokes) {
        for (const p of stroke.points) {
          p.x += dx;
          p.y += dy;
        }
        stroke.roughBox.minX += dx;
        stroke.roughBox.maxX += dx;
        stroke.roughBox.minY += dy;
        stroke.roughBox.maxY += dy;
      }

      this.selectionBBox.minX += dx;
      this.selectionBBox.maxX += dx;
      this.selectionBBox.minY += dy;
      this.selectionBBox.maxY += dy;

      this.dragStartX = pt.x;
      this.dragStartY = pt.y;

      this.engine.render();
      this.renderSelectionHighlight();
      this.updateFloatingBarPosition();
      return;
    }

    if (this.isSelecting) {
      this.lassoPoints.push(pt);
      this.renderLasso();
    }
  }

  onPointerUp(e) {
    if (!this.isActive) return;

    if (this.isDraggingSelection) {
      this.isDraggingSelection = false;
      if (this.engine.onStrokeEnd) this.engine.onStrokeEnd();
      return;
    }

    if (this.isSelecting) {
      this.isSelecting = false;
      this.evaluateSelection();
      this.lassoPoints = [];
      this.clearOverlay();
      if (this.selectedStrokes.length > 0) {
        this.renderSelectionHighlight();
        this.showFloatingBar();
      } else {
        this.hideFloatingBar();
      }
    }
  }

  renderLasso() {
    const ctx = this.overlayCtx;
    ctx.clearRect(0, 0, this.overlayCanvas.width, this.overlayCanvas.height);
    if (this.lassoPoints.length < 2) return;

    ctx.save();
    ctx.strokeStyle = '#2563eb';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([6, 4]);
    ctx.fillStyle = 'rgba(37, 99, 235, 0.08)';

    ctx.beginPath();
    ctx.moveTo(this.lassoPoints[0].x, this.lassoPoints[0].y);
    for (let i = 1; i < this.lassoPoints.length; i++) {
      ctx.lineTo(this.lassoPoints[i].x, this.lassoPoints[i].y);
    }
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();
  }

  evaluateSelection() {
    if (this.lassoPoints.length < 3) return;

    const matched = [];
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

    for (const stroke of this.engine.strokes) {
      let strokeInside = false;
      for (const p of stroke.points) {
        if (this.pointInPolygon(p, this.lassoPoints)) {
          strokeInside = true;
          break;
        }
      }

      if (strokeInside) {
        matched.push(stroke);
        minX = Math.min(minX, stroke.roughBox.minX);
        minY = Math.min(minY, stroke.roughBox.minY);
        maxX = Math.max(maxX, stroke.roughBox.maxX);
        maxY = Math.max(maxY, stroke.roughBox.maxY);
      }
    }

    this.selectedStrokes = matched;
    if (matched.length > 0) {
      const padding = 12;
      this.selectionBBox = {
        minX: minX - padding,
        minY: minY - padding,
        maxX: maxX + padding,
        maxY: maxY + padding
      };
    } else {
      this.selectionBBox = null;
    }
  }

  pointInPolygon(point, polygon) {
    let inside = false;
    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
      const xi = polygon[i].x, yi = polygon[i].y;
      const xj = polygon[j].x, yj = polygon[j].y;

      const intersect = ((yi > point.y) !== (yj > point.y))
          && (point.x < (xj - xi) * (point.y - yi) / (yj - yi) + xi);
      if (intersect) inside = !inside;
    }
    return inside;
  }

  isPointInBBox(pt, box) {
    if (!box) return false;
    return pt.x >= box.minX && pt.x <= box.maxX && pt.y >= box.minY && pt.y <= box.maxY;
  }

  renderSelectionHighlight() {
    const ctx = this.overlayCtx;
    ctx.clearRect(0, 0, this.overlayCanvas.width, this.overlayCanvas.height);
    if (!this.selectionBBox) return;

    const { minX, minY, maxX, maxY } = this.selectionBBox;
    const w = maxX - minX;
    const h = maxY - minY;

    ctx.save();
    ctx.strokeStyle = '#2563eb';
    ctx.lineWidth = 2;
    ctx.setLineDash([4, 4]);
    ctx.fillStyle = 'rgba(37, 99, 235, 0.05)';
    ctx.strokeRect(minX, minY, w, h);
    ctx.fillRect(minX, minY, w, h);

    // Pequeños tiradores en las 4 esquinas
    const handleSize = 8;
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = '#2563eb';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([]);
    const corners = [
      [minX, minY], [maxX, minY],
      [minX, maxY], [maxX, maxY]
    ];
    for (const [cx, cy] of corners) {
      ctx.fillRect(cx - handleSize/2, cy - handleSize/2, handleSize, handleSize);
      ctx.strokeRect(cx - handleSize/2, cy - handleSize/2, handleSize, handleSize);
    }
    ctx.restore();
  }

  updateFloatingBarPosition() {
    if (!this.selectionBBox || !this.floatingBar) return;
    const rect = this.canvas.getBoundingClientRect();
    const scaleX = rect.width / this.canvas.width;
    const scaleY = rect.height / this.canvas.height;

    const screenX = (this.selectionBBox.minX + (this.selectionBBox.maxX - this.selectionBBox.minX) / 2) * scaleX;
    const screenY = this.selectionBBox.minY * scaleY - 48;

    this.floatingBar.style.left = `${Math.max(10, screenX)}px`;
    this.floatingBar.style.top = `${Math.max(10, screenY)}px`;
  }

  showFloatingBar() {
    this.floatingBar.classList.remove('hidden');
    this.updateFloatingBarPosition();
  }

  hideFloatingBar() {
    this.floatingBar.classList.add('hidden');
  }

  clearOverlay() {
    this.overlayCtx.clearRect(0, 0, this.overlayCanvas.width, this.overlayCanvas.height);
  }

  clearSelection() {
    this.selectedStrokes = [];
    this.selectionBBox = null;
    this.clearOverlay();
    this.hideFloatingBar();
  }

  duplicateSelection() {
    if (this.selectedStrokes.length === 0) return;
    const duplicates = [];
    const offset = 20;

    for (const stroke of this.selectedStrokes) {
      const copy = JSON.parse(JSON.stringify(stroke));
      copy.id = 'stroke_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6);
      for (const pt of copy.points) {
        pt.x += offset;
        pt.y += offset;
      }
      copy.roughBox.minX += offset;
      copy.roughBox.maxX += offset;
      copy.roughBox.minY += offset;
      copy.roughBox.maxY += offset;

      this.engine.strokes.push(copy);
      this.engine.pushAction({ type: 'add', stroke: copy });
      duplicates.push(copy);
    }

    this.selectedStrokes = duplicates;
    this.selectionBBox.minX += offset;
    this.selectionBBox.maxX += offset;
    this.selectionBBox.minY += offset;
    this.selectionBBox.maxY += offset;

    this.engine.render();
    this.renderSelectionHighlight();
    this.updateFloatingBarPosition();
    if (this.engine.onStrokeEnd) this.engine.onStrokeEnd();
  }

  deleteSelection() {
    if (this.selectedStrokes.length === 0) return;
    const ids = new Set(this.selectedStrokes.map(s => s.id));
    const deleted = [];

    this.engine.strokes = this.engine.strokes.filter((s, idx) => {
      if (ids.has(s.id)) {
        deleted.push({ stroke: s, index: idx });
        return false;
      }
      return true;
    });

    this.engine.pushAction({ type: 'delete_multiple', strokes: deleted });
    this.clearSelection();
    this.engine.render();
    if (this.engine.onStrokeEnd) this.engine.onStrokeEnd();
  }

  changeSelectionColor(color) {
    if (this.selectedStrokes.length === 0) return;
    for (const stroke of this.selectedStrokes) {
      stroke.color = color;
    }
    this.engine.render();
    if (this.engine.onStrokeEnd) this.engine.onStrokeEnd();
  }
}



// === File: js/editor/toolbar.js ===
// js/editor/toolbar.js - Barra de herramientas simplificada y moderna con mini-menús expansibles
class Toolbar {
  constructor(canvasEngine, selectionTool, options = {}) {
    this.engine = canvasEngine;
    this.selectionTool = selectionTool;
    this.shapeTool = options.shapeTool || null;
    this.textTool = options.textTool || null;
    this.imageTool = options.imageTool || null;

    this.onBack = options.onBack || (() => {});
    this.onTitleChange = options.onTitleChange || (() => {});
    this.onExport = options.onExport || (() => {});
    this.onOpenCover = options.onOpenCover || (() => {});
    this.onPatternChange = options.onPatternChange || (() => {});
    this.onPrevPage = options.onPrevPage || (() => {});
    this.onNextPage = options.onNextPage || (() => {});
    this.onAddPage = options.onAddPage || (() => {});
    this.onDuplicatePage = options.onDuplicatePage || (() => {});
    this.onDeletePage = options.onDeletePage || (() => {});
    this.onOpenSettings = options.onOpenSettings || (() => {});

    this.activeTool = 'pen';
    this.lastPenTool = 'pen';
    this.activeMenu = null; // 'pens' | 'eraser' | 'insert' | 'pages' | 'options' | null

    this.favoriteColors = ['#1e293b', '#2563eb', '#dc2626', '#16a34a', '#d97706', '#9333ea'];
    this.container = null;
    this.popover = null;
    this.currentPageIndex = 0;
    this.totalContentPages = 1;

    this.init();
  }

  init() {
    this.container = document.getElementById('editorToolbar');
    this.renderToolbar();
    this.createPopover();
    this.bindEvents();
    this.updateActiveButton();
  }

  setTools({ shapeTool, textTool, imageTool }) {
    if (shapeTool) this.shapeTool = shapeTool;
    if (textTool) this.textTool = textTool;
    if (imageTool) this.imageTool = imageTool;
  }

  renderToolbar() {
    const isNotebook = this.engine.format === 'a4';

    this.container.innerHTML = `
      <div class="toolbar-left">
        <button id="btnBackToLibrary" class="tool-btn icon-btn" title="Volver a Documentos">
          ${Icons.back}
          <span class="btn-text">Documentos</span>
        </button>
        <div class="doc-title-container">
          <input type="text" id="docTitleInput" class="doc-title-input" value="Sin Título" />
          <span class="save-status" id="saveStatus">${Icons.check}</span>
        </div>
      </div>

      <div class="toolbar-center">
        <!-- Dock principal simplificado -->
        <div class="main-tool-dock">
          <!-- 1. Menú de Plumas / Trazos -->
          <button class="dock-btn has-dropdown active" id="btnMenuPens" title="Trazos y Plumas (Bolígrafo, Lápiz, Rotulador, Subrayador)">
            <span class="tool-icon-wrapper" id="activePenIcon">${Icons.pen}</span>
            <span class="pen-color-dot" id="activePenColorDot" style="background-color: ${this.engine.strokeColor};"></span>
            <span class="dropdown-chevron">${Icons.chevronDown}</span>
          </button>

          <!-- 2. Menú de Borrador -->
          <button class="dock-btn has-dropdown" id="btnMenuEraser" title="Borrador (Trazo o Área)">
            <span class="tool-icon-wrapper">${Icons.eraser}</span>
            <span class="dropdown-chevron">${Icons.chevronDown}</span>
          </button>

          <!-- 3. Mano / Desplazar por el documento -->
          <button class="dock-btn" id="btnToolHand" title="Mano (Moverse y bajar por el documento)">
            <span class="tool-icon-wrapper">${Icons.hand}</span>
          </button>

          <!-- 4. Menú de Insertar -->
          <button class="dock-btn has-dropdown" id="btnMenuInsert" title="Insertar figuras, texto, imágenes o selección">
            <span class="tool-icon-wrapper">${Icons.plus}</span>
            <span class="btn-text">Insertar</span>
            <span class="dropdown-chevron">${Icons.chevronDown}</span>
          </button>

          <div class="dock-divider"></div>

          <!-- 5. Deshacer / Rehacer -->
          <button class="dock-btn-icon" id="btnUndo" title="Deshacer (Ctrl+Z)">
            ${Icons.undo}
          </button>
          <button class="dock-btn-icon" id="btnRedo" title="Rehacer (Ctrl+Y)">
            ${Icons.redo}
          </button>
        </div>
      </div>

      <div class="toolbar-right">
        <!-- 6. Control de Páginas (Cuadernos A4) -->
        <div class="pages-control-group ${isNotebook ? '' : 'hidden'}" id="pagesControlGroup">
          <button class="pages-nav-arrow" id="btnPrevPage" title="Página anterior">
            ${Icons.chevronLeft}
          </button>
          <button class="pages-dropdown-btn" id="btnPagesMenu" title="Menú de Páginas y Pauta">
            <span class="pages-label" id="pagesNavBadge">Pág 1 / 1</span>
            <span class="dropdown-chevron">${Icons.chevronDown}</span>
          </button>
          <button class="pages-nav-arrow" id="btnNextPage" title="Página siguiente">
            ${Icons.chevronRight}
          </button>
        </div>

        <!-- 7. Menú de Configuración -->
        <button class="dock-btn has-dropdown" id="btnMenuSettings" title="Configuración del Sistema y Modo Oscuro">
          <span class="tool-icon-wrapper">${Icons.settings}</span>
          <span class="btn-text">Configuración</span>
          <span class="dropdown-chevron">${Icons.chevronDown}</span>
        </button>
      </div>
    `;
  }

  createPopover() {
    this.popover = document.createElement('div');
    this.popover.className = 'tool-popover mini-menu-popover hidden';
    document.body.appendChild(this.popover);
  }

  bindEvents() {
    // Volver a la biblioteca
    this.container.querySelector('#btnBackToLibrary').addEventListener('click', () => {
      this.closeMenu();
      this.onBack();
    });

    // Edición de título
    const titleInput = this.container.querySelector('#docTitleInput');
    titleInput.addEventListener('change', (e) => {
      this.onTitleChange(e.target.value.trim());
    });

    // 1. Plumas
    const btnMenuPens = this.container.querySelector('#btnMenuPens');
    btnMenuPens.addEventListener('click', (e) => {
      e.stopPropagation();
      const isCurrentPen = ['pen', 'pencil', 'marker', 'highlighter'].includes(this.activeTool);
      if (!isCurrentPen) {
        this.selectTool(this.lastPenTool || 'pen');
      }
      this.toggleMenu('pens', btnMenuPens);
    });

    // 2. Borrador
    const btnMenuEraser = this.container.querySelector('#btnMenuEraser');
    btnMenuEraser.addEventListener('click', (e) => {
      e.stopPropagation();
      if (this.activeTool !== 'eraser') {
        this.selectTool('eraser');
      }
      this.toggleMenu('eraser', btnMenuEraser);
    });

    // 3. Mano
    const btnToolHand = this.container.querySelector('#btnToolHand');
    btnToolHand.addEventListener('click', (e) => {
      e.stopPropagation();
      this.closeMenu();
      this.selectTool('hand');
    });

    // 4. Insertar
    const btnMenuInsert = this.container.querySelector('#btnMenuInsert');
    btnMenuInsert.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggleMenu('insert', btnMenuInsert);
    });

    // 5. Historial
    this.container.querySelector('#btnUndo').addEventListener('click', () => {
      this.engine.undo();
    });

    this.container.querySelector('#btnRedo').addEventListener('click', () => {
      this.engine.redo();
    });

    // 6. Páginas
    const btnPrevPage = this.container.querySelector('#btnPrevPage');
    if (btnPrevPage) {
      btnPrevPage.addEventListener('click', (e) => {
        e.stopPropagation();
        this.closeMenu();
        this.onPrevPage();
      });
    }

    const btnNextPage = this.container.querySelector('#btnNextPage');
    if (btnNextPage) {
      btnNextPage.addEventListener('click', (e) => {
        e.stopPropagation();
        this.closeMenu();
        this.onNextPage();
      });
    }

    const btnPagesMenu = this.container.querySelector('#btnPagesMenu');
    if (btnPagesMenu) {
      btnPagesMenu.addEventListener('click', (e) => {
        e.stopPropagation();
        this.toggleMenu('pages', btnPagesMenu);
      });
    }

    // 7. Configuración
    const btnMenuSettings = this.container.querySelector('#btnMenuSettings');
    if (btnMenuSettings) {
      btnMenuSettings.addEventListener('click', (e) => {
        e.stopPropagation();
        this.toggleMenu('settings', btnMenuSettings);
      });
    }

    // Cerrar menú al hacer clic fuera
    document.addEventListener('pointerdown', (e) => {
      if (
        this.popover &&
        !this.popover.contains(e.target) &&
        !e.target.closest('.has-dropdown') &&
        !e.target.closest('#btnPagesMenu') &&
        !e.target.closest('#btnMenuSettings')
      ) {
        this.closeMenu();
      }
    });

    // Atajos de teclado
    window.addEventListener('keydown', (e) => {
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;

      if (e.key === 'Escape') {
        this.closeMenu();
      } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') {
        e.preventDefault();
        if (e.shiftKey) this.engine.redo();
        else this.engine.undo();
      } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'y') {
        e.preventDefault();
        this.engine.redo();
      } else if (e.key.toLowerCase() === 'p') {
        this.selectTool('pen');
      } else if (e.key.toLowerCase() === 'e') {
        this.selectTool('eraser');
      } else if (e.key.toLowerCase() === 'h') {
        this.selectTool('highlighter');
      } else if (e.key.toLowerCase() === 'm') {
        this.selectTool('hand');
      } else if (e.key.toLowerCase() === 'l') {
        this.selectTool('lasso');
      }
    });
  }

  toggleMenu(menuType, anchorBtn) {
    if (this.activeMenu === menuType) {
      this.closeMenu();
    } else {
      this.openMenu(menuType, anchorBtn);
    }
  }

  openMenu(menuType, anchorBtn) {
    this.activeMenu = menuType;
    this.renderMenuContent(menuType);
    this.positionPopover(anchorBtn);
    this.popover.classList.remove('hidden');
  }

  closeMenu() {
    this.activeMenu = null;
    if (this.popover) {
      this.popover.classList.add('hidden');
    }
  }

  positionPopover(anchorBtn) {
    if (!this.popover || !anchorBtn) return;
    const rect = anchorBtn.getBoundingClientRect();
    const popoverWidth = Math.min(320, window.innerWidth - 20);
    let left = rect.left + rect.width / 2 - popoverWidth / 2;
    left = Math.max(10, Math.min(window.innerWidth - popoverWidth - 10, left));

    let top = rect.bottom + 8;
    this.popover.style.top = `${top}px`;
    this.popover.style.left = `${left}px`;
    this.popover.style.maxWidth = `calc(100vw - 20px)`;
  }

  renderMenuContent(menuType) {
    switch (menuType) {
      case 'pens':
        this.renderPensMenu();
        break;
      case 'eraser':
        this.renderEraserMenu();
        break;
      case 'insert':
        this.renderInsertMenu();
        break;
      case 'pages':
        this.renderPagesMenu();
        break;
      case 'settings':
      case 'options':
        this.renderSettingsMenu();
        break;
    }
  }

  // 1. Mini-menú de Plumas
  renderPensMenu() {
    const penTools = [
      { id: 'pen', name: 'Bolígrafo', icon: Icons.pen, desc: 'Trazo suave continuo' },
      { id: 'pencil', name: 'Lápiz', icon: Icons.pencil, desc: 'Textura de grafito' },
      { id: 'marker', name: 'Rotulador', icon: Icons.marker, desc: 'Tinta densa' },
      { id: 'highlighter', name: 'Subrayador', icon: Icons.highlighter, desc: 'Translúcido con auto-recta' }
    ];

    const currentPenId = ['pen', 'pencil', 'marker', 'highlighter'].includes(this.activeTool)
      ? this.activeTool
      : (this.lastPenTool || 'pen');
    const currentColor = this.engine.strokeColor;
    const currentWidth = this.engine.strokeWidth;
    const currentStabilization = this.engine.strokeStabilization !== undefined ? this.engine.strokeStabilization : 0.5;
    const currentStabilizationPercent = Math.round(currentStabilization * 100);
    const currentConcentration = this.engine.strokeConcentration !== undefined ? this.engine.strokeConcentration : 1.0;
    const currentConcentrationPercent = Math.round(currentConcentration * 100);
    const isHighlighter = currentPenId === 'highlighter';

    const baseOp = isHighlighter ? 0.45 : (currentPenId === 'pencil' ? 0.85 : 1.0);
    const previewOpacity = Math.max(0.1, baseOp * currentConcentration);

    this.popover.innerHTML = `
      <div class="popover-arrow"></div>
      <div class="mini-menu-title">Tipo de Trazo</div>
      <div class="pen-types-grid">
        ${penTools.map(p => `
          <button class="pen-type-chip ${p.id === currentPenId ? 'active' : ''}" data-pentype="${p.id}">
            <span class="pen-chip-icon">${p.icon}</span>
            <span class="pen-chip-name">${p.name}</span>
          </button>
        `).join('')}
      </div>

      <div class="popover-divider"></div>

      <div class="mini-menu-title">Color de Tinta</div>
      <div class="color-palette">
        ${this.favoriteColors.map(c => `
          <button class="color-swatch ${c === currentColor ? 'active' : ''}" data-color="${c}" style="background-color: ${c}"></button>
        `).join('')}
        <label class="color-picker-label" title="Color personalizado">
          <input type="color" id="popoverColorPicker" value="${currentColor}" />
          <span class="picker-icon">${Icons.edit}</span>
        </label>
      </div>

      <div class="popover-divider"></div>

      <!-- Grosor -->
      <div class="popover-row">
        <span class="label-text">Grosor</span>
        <span class="value-text" id="penWidthVal">${currentWidth}px</span>
      </div>
      <div class="slider-with-preview">
        <input type="range" class="popover-slider" id="penStrokeSlider" min="1" max="${isHighlighter ? 40 : 30}" value="${currentWidth}" />
        <div class="stroke-preview-circle" id="penPreviewCircle" style="width: ${Math.min(currentWidth, 28)}px; height: ${Math.min(currentWidth, 28)}px; background-color: ${currentColor}; opacity: ${previewOpacity};"></div>
      </div>
      <div class="stroke-presets-chips" id="widthPresetsGroup">
        ${[1, 2, 4, 8, 14, 24].map(w => `
          <button class="stroke-preset-chip ${w === currentWidth ? 'active' : ''}" data-width="${w}">${w}px</button>
        `).join('')}
      </div>

      <div class="popover-divider"></div>

      <!-- Estabilidad / Suavizado -->
      <div class="popover-row">
        <span class="label-text">Estabilidad (Suavizado)</span>
        <span class="value-text" id="penStabilizationVal">${currentStabilizationPercent}%</span>
      </div>
      <input type="range" class="popover-slider" id="penStabilizationSlider" min="0" max="100" value="${currentStabilizationPercent}" />
      <div class="stroke-presets-chips" id="stabPresetsGroup">
        <button class="stroke-preset-chip ${currentStabilizationPercent === 0 ? 'active' : ''}" data-stab="0">0% Directo</button>
        <button class="stroke-preset-chip ${currentStabilizationPercent === 40 ? 'active' : ''}" data-stab="40">40% Natural</button>
        <button class="stroke-preset-chip ${currentStabilizationPercent === 70 ? 'active' : ''}" data-stab="70">70% Suave</button>
        <button class="stroke-preset-chip ${currentStabilizationPercent === 90 ? 'active' : ''}" data-stab="90">90% Preciso</button>
      </div>

      <div class="popover-divider"></div>

      <!-- Concentración / Densidad de Tinta -->
      <div class="popover-row">
        <span class="label-text">Concentración (Densidad)</span>
        <span class="value-text" id="penConcentrationVal">${currentConcentrationPercent}%</span>
      </div>
      <input type="range" class="popover-slider" id="penConcentrationSlider" min="10" max="100" value="${currentConcentrationPercent}" />
      <div class="stroke-presets-chips" id="concPresetsGroup">
        <button class="stroke-preset-chip ${currentConcentrationPercent === 25 ? 'active' : ''}" data-conc="25">25% Acuarela</button>
        <button class="stroke-preset-chip ${currentConcentrationPercent === 50 ? 'active' : ''}" data-conc="50">50% Medio</button>
        <button class="stroke-preset-chip ${currentConcentrationPercent === 75 ? 'active' : ''}" data-conc="75">75% Denso</button>
        <button class="stroke-preset-chip ${currentConcentrationPercent === 100 ? 'active' : ''}" data-conc="100">100% Sólido</button>
      </div>

      ${isHighlighter ? `
        <div class="popover-hint">
          💡 <strong>Tip:</strong> Mantén pulsado 450ms al final para enderezar automáticamente la línea.
        </div>
      ` : ''}
    `;

    const updatePreviewCircle = () => {
      const circle = this.popover.querySelector('#penPreviewCircle');
      if (circle) {
        const w = this.engine.strokeWidth;
        const c = this.engine.strokeColor;
        const conc = this.engine.strokeConcentration !== undefined ? this.engine.strokeConcentration : 1.0;
        const isHl = this.activeTool === 'highlighter';
        const op = isHl ? 0.45 : (this.activeTool === 'pencil' ? 0.85 : 1.0);
        circle.style.width = `${Math.min(w, 28)}px`;
        circle.style.height = `${Math.min(w, 28)}px`;
        circle.style.backgroundColor = c;
        circle.style.opacity = Math.max(0.1, op * conc);
      }
    };

    // Eventos de selección de tipo de pluma
    this.popover.querySelectorAll('[data-pentype]').forEach(btn => {
      btn.addEventListener('click', () => {
        const penId = btn.dataset.pentype;
        this.selectTool(penId);
        this.renderPensMenu();
      });
    });

    // Eventos de paleta de colores
    this.popover.querySelectorAll('.color-swatch').forEach(swatch => {
      swatch.addEventListener('click', () => {
        const color = swatch.dataset.color;
        this.engine.setColor(color);
        this.updatePenIconColor();
        this.renderPensMenu();
      });
    });

    // Color picker
    const picker = this.popover.querySelector('#popoverColorPicker');
    if (picker) {
      picker.addEventListener('input', (e) => {
        const color = e.target.value;
        this.engine.setColor(color);
        this.updatePenIconColor();
        updatePreviewCircle();
      });
    }

    // Grosor Slider
    const strokeSlider = this.popover.querySelector('#penStrokeSlider');
    if (strokeSlider) {
      strokeSlider.addEventListener('input', (e) => {
        const w = Number(e.target.value);
        this.engine.setWidth(w);
        const valText = this.popover.querySelector('#penWidthVal');
        if (valText) valText.textContent = `${w}px`;
        updatePreviewCircle();
        // Actualizar chips activos
        this.popover.querySelectorAll('#widthPresetsGroup .stroke-preset-chip').forEach(chip => {
          chip.classList.toggle('active', Number(chip.dataset.width) === w);
        });
      });
    }

    // Grosor Presets Chips
    this.popover.querySelectorAll('#widthPresetsGroup .stroke-preset-chip').forEach(chip => {
      chip.addEventListener('click', () => {
        const w = Number(chip.dataset.width);
        this.engine.setWidth(w);
        if (strokeSlider) strokeSlider.value = w;
        const valText = this.popover.querySelector('#penWidthVal');
        if (valText) valText.textContent = `${w}px`;
        updatePreviewCircle();
        this.popover.querySelectorAll('#widthPresetsGroup .stroke-preset-chip').forEach(c => {
          c.classList.toggle('active', c === chip);
        });
      });
    });

    // Estabilidad Slider
    const stabSlider = this.popover.querySelector('#penStabilizationSlider');
    if (stabSlider) {
      stabSlider.addEventListener('input', (e) => {
        const sVal = Number(e.target.value);
        this.engine.setStabilization(sVal / 100);
        const valText = this.popover.querySelector('#penStabilizationVal');
        if (valText) valText.textContent = `${sVal}%`;
        this.popover.querySelectorAll('#stabPresetsGroup .stroke-preset-chip').forEach(chip => {
          chip.classList.toggle('active', Number(chip.dataset.stab) === sVal);
        });
      });
    }

    // Estabilidad Presets Chips
    this.popover.querySelectorAll('#stabPresetsGroup .stroke-preset-chip').forEach(chip => {
      chip.addEventListener('click', () => {
        const sVal = Number(chip.dataset.stab);
        this.engine.setStabilization(sVal / 100);
        if (stabSlider) stabSlider.value = sVal;
        const valText = this.popover.querySelector('#penStabilizationVal');
        if (valText) valText.textContent = `${sVal}%`;
        this.popover.querySelectorAll('#stabPresetsGroup .stroke-preset-chip').forEach(c => {
          c.classList.toggle('active', c === chip);
        });
      });
    });

    // Concentración Slider
    const concSlider = this.popover.querySelector('#penConcentrationSlider');
    if (concSlider) {
      concSlider.addEventListener('input', (e) => {
        const cVal = Number(e.target.value);
        this.engine.setConcentration(cVal / 100);
        const valText = this.popover.querySelector('#penConcentrationVal');
        if (valText) valText.textContent = `${cVal}%`;
        updatePreviewCircle();
        this.popover.querySelectorAll('#concPresetsGroup .stroke-preset-chip').forEach(chip => {
          chip.classList.toggle('active', Number(chip.dataset.conc) === cVal);
        });
      });
    }

    // Concentración Presets Chips
    this.popover.querySelectorAll('#concPresetsGroup .stroke-preset-chip').forEach(chip => {
      chip.addEventListener('click', () => {
        const cVal = Number(chip.dataset.conc);
        this.engine.setConcentration(cVal / 100);
        if (concSlider) concSlider.value = cVal;
        const valText = this.popover.querySelector('#penConcentrationVal');
        if (valText) valText.textContent = `${cVal}%`;
        updatePreviewCircle();
        this.popover.querySelectorAll('#concPresetsGroup .stroke-preset-chip').forEach(c => {
          c.classList.toggle('active', c === chip);
        });
      });
    });
  }

  // 2. Mini-menú de Borrador
  renderEraserMenu() {
    const isStroke = this.engine.eraserMode === 'stroke';
    const radius = this.engine.eraserRadius || 16;
    const highlighterOnly = Boolean(this.engine.eraseHighlighterOnly);

    this.popover.innerHTML = `
      <div class="popover-arrow"></div>
      <div class="mini-menu-title">Modo del Borrador</div>
      <div class="eraser-mode-selector">
        <button class="mode-pill ${isStroke ? 'active' : ''}" id="btnModeStroke">
          Trazo Completo
        </button>
        <button class="mode-pill ${!isStroke ? 'active' : ''}" id="btnModeArea">
          Área Circular
        </button>
      </div>

      <div class="popover-divider"></div>

      <label class="popover-checkbox">
        <input type="checkbox" id="chkHighlighterOnly" ${highlighterOnly ? 'checked' : ''} />
        <span>Solo borrar subrayador</span>
      </label>

      <div class="popover-divider"></div>

      <div class="popover-row">
        <span class="label-text">Radio de borrado</span>
        <span class="value-text" id="eraserSizeVal">${radius}px</span>
      </div>
      <input type="range" class="popover-slider" id="sliderEraserRadius" min="6" max="40" value="${radius}" />
    `;

    this.popover.querySelector('#btnModeStroke').addEventListener('click', () => {
      this.engine.setEraserMode('stroke');
      this.renderEraserMenu();
    });

    this.popover.querySelector('#btnModeArea').addEventListener('click', () => {
      this.engine.setEraserMode('area');
      this.renderEraserMenu();
    });

    this.popover.querySelector('#chkHighlighterOnly').addEventListener('change', (e) => {
      this.engine.setEraseHighlighterOnly(e.target.checked);
    });

    const radiusSlider = this.popover.querySelector('#sliderEraserRadius');
    radiusSlider.addEventListener('input', (e) => {
      const r = Number(e.target.value);
      this.engine.eraserRadius = r;
      const sizeVal = this.popover.querySelector('#eraserSizeVal');
      if (sizeVal) sizeVal.textContent = `${r}px`;
    });
  }

  // 3. Mini-menú de Insertar (Figuras, Texto, Imagen, Lazo)
  renderInsertMenu() {
    const isShape = this.activeTool === 'shape';
    const activeShapeType = this.shapeTool ? this.shapeTool.shapeType : 'rectangle';
    const shapeColor = this.shapeTool ? this.shapeTool.strokeColor : this.engine.strokeColor;
    const fillColor = this.shapeTool ? this.shapeTool.fillColor : 'transparent';
    const shapeWidth = this.shapeTool ? this.shapeTool.strokeWidth : 3;

    const fillColors = [
      { label: 'Ninguno', val: 'transparent' },
      { label: 'Blanco', val: '#ffffff' },
      { label: 'Amarillo', val: '#fef3c7' },
      { label: 'Azul', val: '#dbeafe' },
      { label: 'Verde', val: '#dcfce7' },
      { label: 'Rojo', val: '#fee2e2' }
    ];

    this.popover.innerHTML = `
      <div class="popover-arrow"></div>
      <div class="mini-menu-title">Insertar Elemento</div>
      <div class="insert-tools-grid">
        <button class="insert-item-btn ${isShape ? 'active' : ''}" id="btnInsertShape">
          <span class="insert-icon">${Icons.shape}</span>
          <span class="insert-name">Figuras</span>
        </button>
        <button class="insert-item-btn ${this.activeTool === 'text' ? 'active' : ''}" id="btnInsertText">
          <span class="insert-icon">${Icons.text}</span>
          <span class="insert-name">Texto</span>
        </button>
        <button class="insert-item-btn" id="btnInsertImage">
          <span class="insert-icon">${Icons.image}</span>
          <span class="insert-name">Imagen</span>
        </button>
        <button class="insert-item-btn ${this.activeTool === 'lasso' ? 'active' : ''}" id="btnInsertLasso">
          <span class="insert-icon">${Icons.lasso}</span>
          <span class="insert-name">Lazo</span>
        </button>
      </div>

      <div id="shapeSubOptions" class="${isShape ? '' : 'hidden'}">
        <div class="popover-divider"></div>
        <div class="mini-menu-title">Tipo de Figura</div>
        <div class="shape-type-selector">
          <button class="mode-pill ${activeShapeType === 'rectangle' ? 'active' : ''}" data-shape="rectangle">
            ${Icons.rectangle} Rectángulo
          </button>
          <button class="mode-pill ${activeShapeType === 'circle' ? 'active' : ''}" data-shape="circle">
            ${Icons.circle} Círculo
          </button>
          <button class="mode-pill ${activeShapeType === 'line' ? 'active' : ''}" data-shape="line">
            ${Icons.line} Línea
          </button>
          <button class="mode-pill ${activeShapeType === 'arrow' ? 'active' : ''}" data-shape="arrow">
            ${Icons.arrow} Flecha
          </button>
        </div>

        <div class="popover-divider"></div>

        <div class="mini-menu-title">Color de Borde</div>
        <div class="color-palette">
          ${this.favoriteColors.map(c => `
            <button class="color-swatch ${c === shapeColor ? 'active' : ''}" data-shape-color="${c}" style="background-color: ${c}"></button>
          `).join('')}
        </div>

        <div class="popover-divider"></div>

        <div class="mini-menu-title">Relleno</div>
        <div class="fill-palette">
          ${fillColors.map(f => `
            <button class="fill-swatch ${f.val === fillColor ? 'active' : ''}" data-fill="${f.val}" style="background-color: ${f.val === 'transparent' ? '#f1f5f9' : f.val}" title="${f.label}">
              ${f.val === 'transparent' ? '✕' : ''}
            </button>
          `).join('')}
        </div>

        <div class="popover-divider"></div>

        <div class="popover-row">
          <span class="label-text">Grosor de borde</span>
          <span class="value-text" id="shapeWidthVal">${shapeWidth}px</span>
        </div>
        <input type="range" class="popover-slider" id="shapeStrokeSlider" min="1" max="15" value="${shapeWidth}" />
      </div>
    `;

    // Eventos de botones
    this.popover.querySelector('#btnInsertShape').addEventListener('click', () => {
      this.selectTool('shape');
      this.renderInsertMenu();
    });

    this.popover.querySelector('#btnInsertText').addEventListener('click', () => {
      this.selectTool('text');
      this.closeMenu();
    });

    this.popover.querySelector('#btnInsertImage').addEventListener('click', () => {
      this.closeMenu();
      if (this.imageTool) this.imageTool.triggerUpload();
    });

    this.popover.querySelector('#btnInsertLasso').addEventListener('click', () => {
      this.selectTool('lasso');
      this.closeMenu();
    });

    if (isShape) {
      this.popover.querySelectorAll('[data-shape]').forEach(btn => {
        btn.addEventListener('click', () => {
          if (this.shapeTool) this.shapeTool.setShapeType(btn.dataset.shape);
          this.renderInsertMenu();
        });
      });

      this.popover.querySelectorAll('[data-shape-color]').forEach(btn => {
        btn.addEventListener('click', () => {
          if (this.shapeTool) this.shapeTool.setStrokeColor(btn.dataset.shapeColor);
          this.renderInsertMenu();
        });
      });

      this.popover.querySelectorAll('[data-fill]').forEach(btn => {
        btn.addEventListener('click', () => {
          if (this.shapeTool) this.shapeTool.setFillColor(btn.dataset.fill);
          this.renderInsertMenu();
        });
      });

      const slider = this.popover.querySelector('#shapeStrokeSlider');
      if (slider) {
        slider.addEventListener('input', (e) => {
          const w = Number(e.target.value);
          if (this.shapeTool) this.shapeTool.setStrokeWidth(w);
          const valText = this.popover.querySelector('#shapeWidthVal');
          if (valText) valText.textContent = `${w}px`;
        });
      }
    }
  }

  // 4. Mini-menú de Páginas (Navegación, Añadir, Duplicar, Pauta)
  renderPagesMenu() {
    const isCover = this.currentPageIndex === -1;
    const currentPattern = this.engine.backgroundPattern;

    const patterns = [
      { id: 'grid', name: 'Cuadrícula 5mm', icon: Icons.patternGrid },
      { id: 'ruled', name: 'Rayado Clásico', icon: Icons.patternRuled },
      { id: 'dots', name: 'Puntos Bullet', icon: Icons.patternDots },
      { id: 'blank', name: 'Blanco Liso', icon: Icons.patternBlank }
    ];

    this.popover.innerHTML = `
      <div class="popover-arrow"></div>
      <div class="mini-menu-title">Páginas del Cuaderno</div>
      <div class="mini-actions-list">
        <button class="mini-action-btn ${isCover ? 'active' : ''}" id="btnMenuCover">
          <span class="mini-action-icon">${Icons.cover}</span>
          <div class="mini-action-text">
            <strong>Ir a la Portada</strong>
            <small>Personalizar la carátula</small>
          </div>
        </button>

        <button class="mini-action-btn" id="btnMenuAddPage">
          <span class="mini-action-icon">${Icons.plus}</span>
          <div class="mini-action-text">
            <strong>Añadir Nueva Página</strong>
            <small>Insertar hoja en el cuaderno</small>
          </div>
        </button>

        <button class="mini-action-btn ${isCover ? 'disabled' : ''}" id="btnMenuDupPage" ${isCover ? 'disabled' : ''}>
          <span class="mini-action-icon">${Icons.copy}</span>
          <div class="mini-action-text">
            <strong>Duplicar Página Actual</strong>
            <small>Crear copia idéntica</small>
          </div>
        </button>

        <button class="mini-action-btn danger ${isCover ? 'disabled' : ''}" id="btnMenuDelPage" ${isCover ? 'disabled' : ''}>
          <span class="mini-action-icon">${Icons.trash}</span>
          <div class="mini-action-text">
            <strong>Eliminar Página Actual</strong>
            <small>Borrar permanentemente</small>
          </div>
        </button>
      </div>

      <div class="popover-divider"></div>

      <div class="mini-menu-title">Pauta de Hoja (Fondo)</div>
      <div class="pattern-selector-grid">
        ${patterns.map(p => `
          <button class="pattern-option-btn ${currentPattern === p.id ? 'active' : ''}" data-pattern="${p.id}">
            <span class="pattern-btn-icon">${p.icon}</span>
            <span class="pattern-btn-name">${p.name}</span>
          </button>
        `).join('')}
      </div>
    `;

    // Eventos
    this.popover.querySelector('#btnMenuCover').addEventListener('click', () => {
      this.closeMenu();
      this.onOpenCover();
    });

    this.popover.querySelector('#btnMenuAddPage').addEventListener('click', () => {
      this.closeMenu();
      this.onAddPage();
    });

    const btnDup = this.popover.querySelector('#btnMenuDupPage');
    if (btnDup && !isCover) {
      btnDup.addEventListener('click', () => {
        this.closeMenu();
        this.onDuplicatePage();
      });
    }

    const btnDel = this.popover.querySelector('#btnMenuDelPage');
    if (btnDel && !isCover) {
      btnDel.addEventListener('click', () => {
        this.closeMenu();
        this.onDeletePage();
      });
    }

    this.popover.querySelectorAll('.pattern-option-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const pat = btn.dataset.pattern;
        this.engine.setBackgroundPattern(pat);
        this.onPatternChange(pat);
        this.renderPagesMenu();
      });
    });
  }

  // 5. Mini-menú de Configuración (Tema, Stylus, Opciones)
  renderSettingsMenu() {
    const isStylus = this.engine.inputMode === 'stylus-first';
    const settings = (typeof SettingsManager !== 'undefined')
      ? SettingsManager.getSettings()
      : { theme: 'light', darkPaper: false, autoStraighten: true };

    this.popover.innerHTML = `
      <div class="popover-arrow"></div>
      <div class="mini-menu-title">Configuración y Aspecto</div>

      <div class="settings-mini-section">
        <div class="settings-mini-label">Tema Visual</div>
        <div class="theme-selector-group mini-theme-selector">
          <button type="button" class="theme-option-btn ${settings.theme === 'light' ? 'active' : ''}" data-mini-theme="light">
            <span class="theme-icon">${Icons.sun}</span>
            <span class="theme-label">Claro</span>
          </button>
          <button type="button" class="theme-option-btn ${settings.theme === 'dark' ? 'active' : ''}" data-mini-theme="dark">
            <span class="theme-icon">${Icons.moon}</span>
            <span class="theme-label">Oscuro</span>
          </button>
          <button type="button" class="theme-option-btn ${settings.theme === 'system' ? 'active' : ''}" data-mini-theme="system">
            <span class="theme-icon">${Icons.monitor}</span>
            <span class="theme-label">Sistema</span>
          </button>
        </div>
      </div>

      <div class="popover-divider"></div>

      <div class="settings-mini-section">
        <label class="settings-toggle-row">
          <div class="toggle-text">
            <div class="toggle-title-badge">
              <strong>Modo Stylus (Palma rechazada)</strong>
              <span class="badge-recommended">Activo</span>
            </div>
            <small>Dibuja solo con stylus; un dedo o mano desplaza</small>
          </div>
          <input type="checkbox" id="chkMiniStylus" class="settings-switch" ${isStylus ? 'checked' : ''} />
        </label>

        <label class="settings-toggle-row mt-2">
          <div class="toggle-text">
            <strong>Papel oscuro en modo noche</strong>
            <small>Fondo de hoja oscuro para descansar la vista</small>
          </div>
          <input type="checkbox" id="chkMiniDarkPaper" class="settings-switch" ${settings.darkPaper ? 'checked' : ''} />
        </label>
      </div>

      <div class="popover-divider"></div>

      <div class="mini-actions-list">
        <button class="mini-action-btn primary" id="btnActionExport">
          <span class="mini-action-icon">${Icons.export}</span>
          <div class="mini-action-text">
            <strong>Exportar Documento</strong>
            <small>Guardar en PDF vectorial o imagen PNG</small>
          </div>
        </button>

        <button class="mini-action-btn danger" id="btnClearPageCanvas">
          <span class="mini-action-icon">${Icons.trash}</span>
          <div class="mini-action-text">
            <strong>Limpiar Lienzo</strong>
            <small>Vaciar trazos y notas de esta página</small>
          </div>
        </button>

        <button class="mini-action-btn" id="btnOpenSettingsFromEditor">
          <span class="mini-action-icon">${Icons.settings}</span>
          <div class="mini-action-text">
            <strong>Panel Completo de Ajustes</strong>
            <small>Pautas por defecto y datos locales</small>
          </div>
        </button>
      </div>
    `;

    // Eventos de Tema
    this.popover.querySelectorAll('[data-mini-theme]').forEach(btn => {
      btn.addEventListener('click', () => {
        const theme = btn.dataset.miniTheme;
        if (typeof SettingsManager !== 'undefined') {
          SettingsManager.saveSettings({ theme });
        }
        this.renderSettingsMenu();
      });
    });

    // Toggle Modo Stylus
    const chkStylus = this.popover.querySelector('#chkMiniStylus');
    if (chkStylus) {
      chkStylus.addEventListener('change', (e) => {
        const newMode = e.target.checked ? 'stylus-first' : 'finger-drawing';
        this.engine.setInputMode(newMode);
        if (typeof SettingsManager !== 'undefined') {
          SettingsManager.saveSettings({ inputMode: newMode });
        }
        this.renderSettingsMenu();
      });
    }

    // Toggle Papel Oscuro
    const chkDarkPaper = this.popover.querySelector('#chkMiniDarkPaper');
    if (chkDarkPaper) {
      chkDarkPaper.addEventListener('change', (e) => {
        if (typeof SettingsManager !== 'undefined') {
          SettingsManager.saveSettings({ darkPaper: e.target.checked });
        }
      });
    }

    this.popover.querySelector('#btnClearPageCanvas').addEventListener('click', () => {
      this.closeMenu();
      if (confirm('¿Deseas vaciar todos los trazos y elementos de la página actual?')) {
        this.engine.clearAll();
      }
    });

    this.popover.querySelector('#btnActionExport').addEventListener('click', () => {
      this.closeMenu();
      this.onExport();
    });

    const btnSettings = this.popover.querySelector('#btnOpenSettingsFromEditor');
    if (btnSettings) {
      btnSettings.addEventListener('click', () => {
        this.closeMenu();
        this.onOpenSettings();
      });
    }
  }

  // Compatibilidad
  renderOptionsMenu() {
    this.renderSettingsMenu();
  }

  selectTool(tool) {
    this.activeTool = tool;
    if (['pen', 'pencil', 'marker', 'highlighter'].includes(tool)) {
      this.lastPenTool = tool;
    }
    this.engine.setTool(tool);
    this.selectionTool.setActive(tool === 'lasso');
    this.updateActiveButton();

    if (tool === 'highlighter') {
      this.engine.setWidth(18);
      this.engine.setOpacity(0.45);
    } else if (tool === 'pen') {
      this.engine.setWidth(3);
      this.engine.setOpacity(1);
    } else if (tool === 'pencil') {
      this.engine.setWidth(2.5);
      this.engine.setOpacity(0.85);
    } else if (tool === 'marker') {
      this.engine.setWidth(6);
      this.engine.setOpacity(0.9);
    }
  }

  updateActiveButton() {
    const isPen = ['pen', 'pencil', 'marker', 'highlighter'].includes(this.activeTool);
    const isEraser = this.activeTool === 'eraser';
    const isHand = this.activeTool === 'hand';
    const isInsert = ['shape', 'text', 'image', 'lasso'].includes(this.activeTool);

    const btnPens = this.container.querySelector('#btnMenuPens');
    const btnEraser = this.container.querySelector('#btnMenuEraser');
    const btnHand = this.container.querySelector('#btnToolHand');
    const btnInsert = this.container.querySelector('#btnMenuInsert');

    if (btnPens) btnPens.classList.toggle('active', isPen);
    if (btnEraser) btnEraser.classList.toggle('active', isEraser);
    if (btnHand) btnHand.classList.toggle('active', isHand);
    if (btnInsert) btnInsert.classList.toggle('active', isInsert);

    // Actualizar icono de la pluma activa
    const iconSpan = this.container.querySelector('#activePenIcon');
    if (iconSpan && isPen) {
      iconSpan.innerHTML = Icons[this.activeTool] || Icons.pen;
    }

    this.updatePenIconColor();
  }

  updatePenIconColor() {
    const dot = this.container.querySelector('#activePenColorDot');
    if (dot) {
      dot.style.backgroundColor = this.engine.strokeColor;
    }
  }

  updatePageCounter(currentIdx, totalContentPages) {
    this.currentPageIndex = currentIdx;
    this.totalContentPages = totalContentPages;

    const badge = this.container.querySelector('#pagesNavBadge');
    if (badge) {
      const isNotebook = this.engine.format === 'a4';
      if (isNotebook) {
        const totalPages = totalContentPages + 1;
        if (currentIdx === -1) {
          badge.textContent = `Pág 1 / ${totalPages} (Portada)`;
        } else {
          badge.textContent = `Pág ${currentIdx + 2} / ${totalPages}`;
        }
      } else {
        badge.textContent = `Pág ${currentIdx + 1} / ${totalContentPages}`;
      }
    }
  }

  setFormat(format) {
    const isNotebook = format === 'a4';
    const pagesGroup = this.container.querySelector('#pagesControlGroup');
    if (pagesGroup) {
      pagesGroup.classList.toggle('hidden', !isNotebook);
    }
  }

  updatePatternIcon() {
    // Pauta se actualiza dentro del mini-menú de páginas si está abierto
    if (this.activeMenu === 'pages') {
      this.renderPagesMenu();
    }
  }

  setDocTitle(title) {
    const input = this.container.querySelector('#docTitleInput');
    if (input) input.value = title || 'Sin Título';
  }

  showSavedStatus() {
    const status = this.container.querySelector('#saveStatus');
    if (status) {
      status.style.opacity = '1';
      setTimeout(() => {
        status.style.opacity = '0.5';
      }, 1500);
    }
  }
}


// === File: js/editor/viewport.js ===
// js/editor/viewport.js - Controlador de Zoom, Paneo y Navegación táctil para el Lienzo
class ViewportController {
  constructor(workspaceEl, wrapperEl, canvasEngine, options = {}) {
    this.workspace = workspaceEl;
    this.wrapper = wrapperEl;
    this.canvas = canvasEngine.canvas;
    this.engine = canvasEngine;

    // Estado del Viewport
    this.zoom = 1.0;
    this.minZoom = 0.25;
    this.maxZoom = 4.0;
    this.panX = 0;
    this.panY = 0;

    // Estados de interacción
    this.isPanning = false;
    this.panStartX = 0;
    this.panStartY = 0;
    this.isSpacePressed = false;

    // Soporte multitáctil (Pellizcar para zoom en tablets / Android)
    this.activeTouches = new Map();
    this.initialPinchDistance = 0;
    this.initialPinchZoom = 1.0;
    this.initialPinchMidpoint = { x: 0, y: 0 };

    this.onZoomChange = options.onZoomChange || (() => {});

    this.widgetEl = null;
    this.createControlsWidget();
    this.bindEvents();
    this.centerContent();
  }

  createControlsWidget() {
    this.widgetEl = document.createElement('div');
    this.widgetEl.className = 'zoom-controls-widget';
    this.widgetEl.innerHTML = `
      <button class="zoom-btn" id="btnZoomOut" title="Reducir zoom (Ctrl + -)">
        ${Icons.zoomOut}
      </button>
      <button class="zoom-btn zoom-percent" id="btnZoomReset" title="Restablecer al 100% (Ctrl + 0)">
        100%
      </button>
      <button class="zoom-btn" id="btnZoomIn" title="Aumentar zoom (Ctrl + +)">
        ${Icons.zoomIn}
      </button>
      <div class="zoom-divider"></div>
      <button class="zoom-btn" id="btnZoomFit" title="Ajustar a la pantalla">
        ${Icons.fitScreen}
      </button>
      <div class="zoom-divider" id="scrollNavDivider"></div>
      <button class="zoom-btn scroll-doc-btn" id="btnScrollDocUp" title="Subir página anterior">
        ${Icons.chevronUp}
      </button>
      <button class="zoom-btn scroll-doc-btn" id="btnScrollDocDown" title="Bajar página siguiente">
        ${Icons.chevronDown}
      </button>
    `;

    this.workspace.appendChild(this.widgetEl);

    // Eventos del widget
    this.widgetEl.querySelector('#btnZoomOut').addEventListener('click', (e) => {
      e.stopPropagation();
      this.zoomOut();
    });

    this.widgetEl.querySelector('#btnZoomIn').addEventListener('click', (e) => {
      e.stopPropagation();
      this.zoomIn();
    });

    this.widgetEl.querySelector('#btnZoomReset').addEventListener('click', (e) => {
      e.stopPropagation();
      if (Math.abs(this.zoom - 1.0) < 0.05) {
        this.fitToScreen();
      } else {
        this.resetZoom();
      }
    });

    this.widgetEl.querySelector('#btnZoomFit').addEventListener('click', (e) => {
      e.stopPropagation();
      this.fitToScreen();
    });

    const btnScrollUp = this.widgetEl.querySelector('#btnScrollDocUp');
    if (btnScrollUp) {
      btnScrollUp.addEventListener('click', (e) => {
        e.stopPropagation();
        this.scrollBy(450);
      });
    }

    const btnScrollDown = this.widgetEl.querySelector('#btnScrollDocDown');
    if (btnScrollDown) {
      btnScrollDown.addEventListener('click', (e) => {
        e.stopPropagation();
        this.scrollBy(-450);
      });
    }
  }

  bindEvents() {
    // 1. Rueda del ratón y trackpad (Zoom con cursor de ancla y desplazamiento)
    this.workspace.addEventListener('wheel', (e) => this.onWheel(e), { passive: false });

    // 2. Teclado (Barra espaciadora para paneo y atajos de zoom)
    window.addEventListener('keydown', (e) => this.onKeyDown(e));
    window.addEventListener('keyup', (e) => this.onKeyUp(e));

    // 3. Eventos de puntero para Paneo y Multitouch
    this.workspace.addEventListener('pointerdown', (e) => this.onPointerDown(e), { capture: true });
    window.addEventListener('pointermove', (e) => this.onPointerMove(e));
    window.addEventListener('pointerup', (e) => this.onPointerUp(e));
    window.addEventListener('pointercancel', (e) => this.onPointerUp(e));

    // Reajustar si la ventana cambia de tamaño
    window.addEventListener('resize', () => {
      this.clampPan();
      this.applyTransform();
    });
  }

  onWheel(e) {
    e.preventDefault();

    const rect = this.workspace.getBoundingClientRect();
    const cursorX = e.clientX - rect.left;
    const cursorY = e.clientY - rect.top;

    // Si mantiene Ctrl/Cmd o pellizca en trackpad: Zoom enfocado al cursor
    if (e.ctrlKey || e.metaKey) {
      const zoomFactor = e.deltaY < 0 ? 1.15 : 0.87;
      this.zoomAt(cursorX, cursorY, this.zoom * zoomFactor);
    } else if (e.shiftKey) {
      // Shift + Rueda: Desplazamiento horizontal
      this.panX -= e.deltaY * 0.8;
      this.applyTransform();
    } else {
      // Rueda normal: Desplazamiento vertical y horizontal por el documento
      this.panY -= e.deltaY * 0.9;
      this.panX -= e.deltaX * 0.9;
      this.clampPan();
      this.applyTransform();
    }
  }

  onKeyDown(e) {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;

    // Barra espaciadora activa modo mano para mover el lienzo
    if (e.code === 'Space' && !this.isSpacePressed) {
      this.isSpacePressed = true;
      this.workspace.classList.add('panning-mode');
    }

    // Atajos de zoom: Ctrl + / Ctrl - / Ctrl 0
    if (e.ctrlKey || e.metaKey) {
      if (e.key === '+' || e.key === '=') {
        e.preventDefault();
        this.zoomIn();
      } else if (e.key === '-') {
        e.preventDefault();
        this.zoomOut();
      } else if (e.key === '0') {
        e.preventDefault();
        this.resetZoom();
      }
    }
  }

  onKeyUp(e) {
    if (e.code === 'Space') {
      this.isSpacePressed = false;
      this.workspace.classList.remove('panning-mode');
    }
  }

  onPointerDown(e) {
    // Si es un toque en pantalla, registrar para detección multitáctil
    if (e.pointerType === 'touch') {
      this.activeTouches.set(e.pointerId, { clientX: e.clientX, clientY: e.clientY });

      if (this.activeTouches.size === 2) {
        // Dos dedos detectados: Iniciar modo pellizco (zoom) y paneo a 2 dedos (scroll)
        this.engine.isDrawing = false;
        this.engine.currentStroke = null;
        this.engine.render();

        const touches = Array.from(this.activeTouches.values());
        this.initialPinchDistance = Math.hypot(
          touches[0].clientX - touches[1].clientX,
          touches[0].clientY - touches[1].clientY
        );
        this.initialPinchZoom = this.zoom;

        const rect = this.workspace.getBoundingClientRect();
        this.initialPinchMidpoint = {
          x: (touches[0].clientX + touches[1].clientX) / 2 - rect.left,
          y: (touches[0].clientY + touches[1].clientY) / 2 - rect.top
        };
        this.lastPinchMidpoint = { ...this.initialPinchMidpoint };
        return;
      }
    }

    // Paneo con botón central del ratón, manteniendo Espacio, con herramienta mano ('hand')
    // O toque táctil si está en modo Stylus (rechazo de palma activo para scroll con dedo)
    const isMiddleClick = e.button === 1;
    const isHandTool = this.engine.tool === 'hand';
    const isStylusTouchPan = e.pointerType === 'touch' && this.engine.inputMode === 'stylus-first';

    if (isMiddleClick || this.isSpacePressed || isHandTool || isStylusTouchPan) {
      e.preventDefault();
      e.stopPropagation();
      this.isPanning = true;
      this.panStartX = e.clientX - this.panX;
      this.panStartY = e.clientY - this.panY;
      this.workspace.classList.add('grabbing');
    }
  }

  onPointerMove(e) {
    // 1. Gestión multitáctil (Pellizco de zoom y paneo a 2 dedos para desplazarse por el documento)
    if (e.pointerType === 'touch' && this.activeTouches.has(e.pointerId)) {
      this.activeTouches.set(e.pointerId, { clientX: e.clientX, clientY: e.clientY });

      if (this.activeTouches.size === 2) {
        const touches = Array.from(this.activeTouches.values());
        const currentDistance = Math.hypot(
          touches[0].clientX - touches[1].clientX,
          touches[0].clientY - touches[1].clientY
        );

        const rect = this.workspace.getBoundingClientRect();
        const currentMidpoint = {
          x: (touches[0].clientX + touches[1].clientX) / 2 - rect.left,
          y: (touches[0].clientY + touches[1].clientY) / 2 - rect.top
        };

        // Paneo / desplazamiento al mover los 2 dedos
        if (this.lastPinchMidpoint) {
          const deltaX = currentMidpoint.x - this.lastPinchMidpoint.x;
          const deltaY = currentMidpoint.y - this.lastPinchMidpoint.y;
          this.panX += deltaX;
          this.panY += deltaY;
        }
        this.lastPinchMidpoint = currentMidpoint;

        // Zoom por pellizco si la distancia cambia significativamente
        if (this.initialPinchDistance > 0 && Math.abs(currentDistance - this.initialPinchDistance) > 12) {
          const factor = currentDistance / this.initialPinchDistance;
          const targetZoom = this.initialPinchZoom * factor;
          this.zoomAt(currentMidpoint.x, currentMidpoint.y, targetZoom);
        } else {
          this.clampPan();
          this.applyTransform();
        }
        return;
      }
    }

    // 2. Paneo activo con ratón, herramienta mano o toque en modo stylus
    if (this.isPanning) {
      this.panX = e.clientX - this.panStartX;
      this.panY = e.clientY - this.panStartY;
      this.clampPan();
      this.applyTransform();
    }
  }

  onPointerUp(e) {
    if (e.pointerType === 'touch') {
      this.activeTouches.delete(e.pointerId);
      if (this.activeTouches.size < 2) {
        this.initialPinchDistance = 0;
        this.lastPinchMidpoint = null;
      }
    }

    if (this.isPanning) {
      this.isPanning = false;
      this.workspace.classList.remove('grabbing');
    }
  }

  // Zoom enfocado en un punto específico de la pantalla (cursor o centro)
  zoomAt(screenX, screenY, targetZoom) {
    const newZoom = Math.max(this.minZoom, Math.min(this.maxZoom, targetZoom));
    if (Math.abs(newZoom - this.zoom) < 0.001) return;

    // Conservar el punto del lienzo bajo las coordenadas del cursor
    const scale = newZoom / this.zoom;
    this.panX = screenX - (screenX - this.panX) * scale;
    this.panY = screenY - (screenY - this.panY) * scale;
    this.zoom = newZoom;

    this.applyTransform();
  }

  zoomIn() {
    const cx = this.workspace.clientWidth / 2;
    const cy = this.workspace.clientHeight / 2;
    this.zoomAt(cx, cy, this.zoom * 1.25);
  }

  zoomOut() {
    const cx = this.workspace.clientWidth / 2;
    const cy = this.workspace.clientHeight / 2;
    this.zoomAt(cx, cy, this.zoom * 0.8);
  }

  resetZoom() {
    const wsWidth = this.workspace.clientWidth || window.innerWidth;
    const canvasWidth = this.engine.canvas.width;
    this.zoom = 1.0;
    this.panX = (wsWidth - canvasWidth) / 2;
    this.panY = 30;
    this.applyTransform();
  }

  fitWidth(padding = 16) {
    const wsWidth = this.workspace.clientWidth || window.innerWidth;
    const targetWidth = this.engine.format === 'a4' ? 794 : this.engine.canvas.width;
    const fitScale = (wsWidth - padding * 2) / targetWidth;
    this.zoom = Math.max(this.minZoom, Math.min(2.0, fitScale));
    this.panX = (wsWidth - targetWidth * this.zoom) / 2;
    this.panY = 16;
    this.applyTransform();
  }

  fitToScreen() {
    const wsWidth = this.workspace.clientWidth || window.innerWidth;
    const wsHeight = this.workspace.clientHeight || (window.innerHeight - 60);

    if (this.engine.format === 'a4') {
      this.fitWidth(wsWidth <= 768 ? 12 : 32);
      return;
    }

    const canvasWidth = this.engine.canvas.width;
    const canvasHeight = this.engine.canvas.height;
    const padding = wsWidth <= 768 ? 16 : 32;

    const fitScale = Math.min(
      (wsWidth - padding * 2) / canvasWidth,
      (wsHeight - padding * 2) / canvasHeight
    );

    this.zoom = Math.max(this.minZoom, Math.min(2.0, fitScale));
    this.panX = (wsWidth - canvasWidth * this.zoom) / 2;
    this.panY = Math.max(16, (wsHeight - canvasHeight * this.zoom) / 2);

    this.applyTransform();
  }

  centerContent() {
    const wsWidth = this.workspace.clientWidth || window.innerWidth;
    const wsHeight = this.workspace.clientHeight || (window.innerHeight - 60);
    const isMobile = wsWidth <= 768;

    if (this.engine.format === 'a4') {
      if (isMobile || 794 > wsWidth - 48) {
        this.fitWidth(isMobile ? 12 : 32);
      } else {
        this.zoom = 1.0;
        this.panX = (wsWidth - 794) / 2;
        this.panY = 24;
        this.applyTransform();
      }
      return;
    }

    const canvasWidth = this.engine.canvas.width;
    const canvasHeight = this.engine.canvas.height;

    if (canvasWidth > wsWidth || canvasHeight > wsHeight) {
      this.fitToScreen();
    } else {
      this.zoom = 1.0;
      this.panX = (wsWidth - canvasWidth) / 2;
      this.panY = Math.max(24, (wsHeight - canvasHeight) / 2);
      this.applyTransform();
    }
  }

  scrollBy(deltaY) {
    this.panY += deltaY;
    this.clampPan();
    this.applyTransform();
  }

  clampPan() {
    let totalHeight = this.engine.canvas.height;
    let totalWidth = this.engine.canvas.width;

    if (this.engine.format === 'a4') {
      const streamContainer = this.wrapper.querySelector('.notebook-stream-container');
      if (streamContainer && streamContainer.scrollHeight > 0) {
        totalHeight = Math.max(totalHeight, streamContainer.scrollHeight);
      } else {
        const pagesCount = this.wrapper.querySelectorAll('.notebook-page-wrapper').length;
        if (pagesCount > 0) {
          totalHeight = Math.max(totalHeight, pagesCount * 1220 + 200);
        }
      }
      totalWidth = 794;
    } else {
      totalHeight = Math.max(totalHeight, 1400);
    }

    const wsWidth = this.workspace.clientWidth || window.innerWidth;
    const wsHeight = this.workspace.clientHeight || (window.innerHeight - 60);

    const contentWidth = totalWidth * this.zoom;
    const contentHeight = totalHeight * this.zoom;

    const minX = Math.min(-contentWidth + 100, (wsWidth - contentWidth) / 2);
    const maxX = Math.max(wsWidth - 100, (wsWidth - contentWidth) / 2);

    // Permite bajar libremente por todo el documento hasta el final
    const maxY = 80;
    const maxScroll = Math.max(200, contentHeight - wsHeight + 350);
    const minY = -maxScroll;

    this.panX = Math.max(minX, Math.min(maxX, this.panX));
    this.panY = Math.min(maxY, Math.max(minY, this.panY));
  }

  applyTransform() {
    this.wrapper.style.transformOrigin = '0 0';
    this.wrapper.style.transform = `translate3d(${this.panX}px, ${this.panY}px, 0) scale(${this.zoom})`;

    // Actualizar indicador del widget
    if (this.widgetEl) {
      const pctBtn = this.widgetEl.querySelector('.zoom-percent');
      if (pctBtn) {
        pctBtn.textContent = `${Math.round(this.zoom * 100)}%`;
      }
    }

    this.onZoomChange(this.zoom);
  }
}



// === File: js/editor/exporter.js ===
// js/editor/exporter.js - Exportación unificada: Compilación multi-página para Cuadernos y recorte automático para Pizarras
class Exporter {
  /**
   * Muestra modal interactivo de exportación adaptado al tipo de documento
   */
  static showExportModal(doc, canvasEngine) {
    const isNotebook = doc.type === 'notebook' || canvasEngine.format === 'a4';
    const existingModal = document.getElementById('exportModal');
    if (existingModal) existingModal.remove();

    const modal = document.createElement('div');
    modal.id = 'exportModal';
    modal.className = 'modal-backdrop';

    modal.innerHTML = `
      <div class="modal-box export-modal-box">
        <h3 class="modal-title">Exportar Documento</h3>
        <p class="export-modal-subtitle">${this.escapeHtml(doc.title)} (${isNotebook ? 'Cuaderno Digital' : 'Pizarra Infinita'})</p>

        <div class="export-options-list">
          ${isNotebook ? `
            <button class="export-option-card primary-card" id="btnExportFullPdf">
              <div class="export-card-icon">${Icons.export}</div>
              <div class="export-card-info">
                <strong>Compilar Cuaderno completo en PDF</strong>
                <small>Incluye portada diseñada y todas las páginas en formato A4 vectorial estándar.</small>
              </div>
            </button>
            <button class="export-option-card" id="btnExportCurrentPng">
              <div class="export-card-icon">${Icons.image}</div>
              <div class="export-card-info">
                <strong>Página actual como Imagen PNG</strong>
                <small>Imagen de alta resolución de la página visible en el editor.</small>
              </div>
            </button>
            <button class="export-option-card" id="btnExportCurrentJpg">
              <div class="export-card-icon">${Icons.image}</div>
              <div class="export-card-info">
                <strong>Página actual como JPG comprimido</strong>
                <small>Formato ligero ideal para compartir rápidamente.</small>
              </div>
            </button>
          ` : `
            <button class="export-option-card primary-card" id="btnExportBoardPng">
              <div class="export-card-icon">${Icons.image}</div>
              <div class="export-card-info">
                <strong>Imagen PNG con Recorte Inteligente</strong>
                <small>Ajusta los bordes automáticamente a todos los dibujos (+ margen de 40px).</small>
              </div>
            </button>
            <button class="export-option-card" id="btnExportBoardJpg">
              <div class="export-card-icon">${Icons.image}</div>
              <div class="export-card-info">
                <strong>Imagen JPG (Fondo blanco nítido)</strong>
                <small>Recorte automático al contenido con fondo blanco puro.</small>
              </div>
            </button>
            <button class="export-option-card" id="btnExportBoardPdf">
              <div class="export-card-icon">${Icons.export}</div>
              <div class="export-card-info">
                <strong>Documento PDF de la Pizarra</strong>
                <small>Exporta el área activa en un documento PDF adaptado.</small>
              </div>
            </button>
          `}
        </div>

        <div class="modal-actions" style="margin-top: 20px;">
          <button class="btn-secondary" id="btnCloseExportModal">Cerrar</button>
        </div>
      </div>
    `;

    document.body.appendChild(modal);

    const close = () => modal.remove();
    modal.querySelector('#btnCloseExportModal').addEventListener('click', close);
    modal.addEventListener('click', (e) => {
      if (e.target === modal) close();
    });

    // Conectar eventos según el tipo
    if (isNotebook) {
      modal.querySelector('#btnExportFullPdf').addEventListener('click', async () => {
        close();
        await this.exportNotebookPdf(doc, canvasEngine);
      });
      modal.querySelector('#btnExportCurrentPng').addEventListener('click', () => {
        close();
        this.exportPageImage(canvasEngine, doc.title, 'png');
      });
      modal.querySelector('#btnExportCurrentJpg').addEventListener('click', () => {
        close();
        this.exportPageImage(canvasEngine, doc.title, 'jpeg');
      });
    } else {
      modal.querySelector('#btnExportBoardPng').addEventListener('click', () => {
        close();
        this.exportWhiteboardImage(canvasEngine, doc.title, 'png');
      });
      modal.querySelector('#btnExportBoardJpg').addEventListener('click', () => {
        close();
        this.exportWhiteboardImage(canvasEngine, doc.title, 'jpeg');
      });
      modal.querySelector('#btnExportBoardPdf').addEventListener('click', () => {
        close();
        this.exportWhiteboardPdf(canvasEngine, doc.title);
      });
    }
  }

  /**
   * Compila un Cuaderno completo (Portada + Todas las páginas) a un PDF unificado
   */
  static async exportNotebookPdf(doc, canvasEngine) {
    const { jsPDF } = window.jspdf;
    const a4W = 794;
    const a4H = 1123;

    const pdf = new jsPDF({
      orientation: 'portrait',
      unit: 'px',
      format: [a4W, a4H]
    });

    let isFirstPage = true;

    // 1. Portada del cuaderno si existe
    if (doc.cover) {
      const coverCanvas = document.createElement('canvas');
      coverCanvas.width = a4W;
      coverCanvas.height = a4H;
      const cCtx = coverCanvas.getContext('2d');

      // Si tiene imagen de fondo personalizada, esperar a que cargue
      if (doc.cover.customImage && !doc.cover._imgElement) {
        await new Promise((resolve) => {
          const img = new Image();
          img.onload = () => { doc.cover._imgElement = img; resolve(); };
          img.onerror = resolve;
          img.src = doc.cover.customImage;
        });
      }

      this.renderPageDataToContext(cCtx, doc.cover, a4W, a4H, canvasEngine);
      const coverImgData = coverCanvas.toDataURL('image/jpeg', 0.95);
      pdf.addImage(coverImgData, 'JPEG', 0, 0, a4W, a4H);
      isFirstPage = false;
    }

    // 2. Iterar sobre las páginas del cuaderno
    const pages = (doc.pages && doc.pages.length > 0) ? doc.pages : [{
      strokes: canvasEngine.strokes,
      shapes: canvasEngine.shapes,
      texts: canvasEngine.texts,
      images: canvasEngine.images,
      backgroundPattern: canvasEngine.backgroundPattern
    }];

    const renderCanvas = document.createElement('canvas');
    renderCanvas.width = a4W;
    renderCanvas.height = a4H;
    const rCtx = renderCanvas.getContext('2d');

    for (let i = 0; i < pages.length; i++) {
      const page = pages[i];
      if (!isFirstPage) {
        pdf.addPage([a4W, a4H], 'portrait');
      } else {
        isFirstPage = false;
      }

      // Pre-cargar imágenes de la página
      if (page.images && page.images.length > 0) {
        for (const imgItem of page.images) {
          if (!imgItem._element && imgItem.dataUrl) {
            const img = new Image();
            img.src = imgItem.dataUrl;
            await new Promise(r => { img.onload = r; img.onerror = r; });
            imgItem._element = img;
          }
        }
      }

      // Renderizado limpio de la página
      this.renderPageDataToContext(rCtx, page, a4W, a4H, canvasEngine);

      const pageImgData = renderCanvas.toDataURL('image/jpeg', 0.95);
      pdf.addImage(pageImgData, 'JPEG', 0, 0, a4W, a4H);
    }

    const cleanTitle = (doc.title || 'Cuaderno').replace(/[^a-z0-9]/gi, '_').toLowerCase();
    const filename = `${cleanTitle}_completo_${new Date().toISOString().slice(0, 10)}.pdf`;
    if (typeof window.saveNativeFile === 'function' && window.isAndroidApp && window.isAndroidApp()) {
      window.saveNativeFile(pdf.output('datauristring'), filename, 'application/pdf');
    } else {
      pdf.save(filename);
    }
  }

  /**
   * Exporta la Pizarra libre con Auto-crop al contenido (+40px margen)
   */
  static exportWhiteboardImage(canvasEngine, title = 'Pizarra', format = 'png') {
    const bbox = canvasEngine.getBoundingBox();
    const margin = 40;

    const minX = Math.max(0, bbox.minX - margin);
    const minY = Math.max(0, bbox.minY - margin);
    const maxX = Math.min(canvasEngine.canvas.width, bbox.maxX + margin);
    const maxY = Math.min(canvasEngine.canvas.height, bbox.maxY + margin);

    const cropW = Math.max(120, maxX - minX);
    const cropH = Math.max(120, maxY - minY);

    // 1. Renderizar lienzo completo a un canvas auxiliar
    const fullCanvas = document.createElement('canvas');
    fullCanvas.width = canvasEngine.canvas.width;
    fullCanvas.height = canvasEngine.canvas.height;
    const fCtx = fullCanvas.getContext('2d');

    // Fondo blanco
    fCtx.fillStyle = '#ffffff';
    fCtx.fillRect(0, 0, fullCanvas.width, fullCanvas.height);
    canvasEngine.renderBackground(fCtx);
    canvasEngine.renderImages(fCtx);

    fCtx.save();
    fCtx.globalCompositeOperation = 'multiply';
    for (const s of canvasEngine.strokes) {
      if (s.isHighlighter) canvasEngine.drawStroke(fCtx, s);
    }
    fCtx.restore();

    fCtx.save();
    for (const sh of canvasEngine.shapes) canvasEngine.drawShape(fCtx, sh);
    for (const s of canvasEngine.strokes) {
      if (!s.isHighlighter) canvasEngine.drawStroke(fCtx, s);
    }
    for (const t of canvasEngine.texts) canvasEngine.drawText(fCtx, t);
    fCtx.restore();

    // 2. Extraer recorte exacto al área ocupada
    const cropCanvas = document.createElement('canvas');
    cropCanvas.width = cropW;
    cropCanvas.height = cropH;
    const cCtx = cropCanvas.getContext('2d');

    cCtx.fillStyle = '#ffffff';
    cCtx.fillRect(0, 0, cropW, cropH);
    cCtx.drawImage(fullCanvas, minX, minY, cropW, cropH, 0, 0, cropW, cropH);

    const cleanTitle = (title || 'Pizarra').replace(/[^a-z0-9]/gi, '_').toLowerCase();
    const mime = format === 'jpeg' ? 'image/jpeg' : 'image/png';
    const ext = format === 'jpeg' ? 'jpg' : 'png';
    const filename = `${cleanTitle}_recorte_${new Date().toISOString().slice(0, 10)}.${ext}`;
    const dataUrl = cropCanvas.toDataURL(mime, 0.95);

    if (typeof window.saveNativeFile === 'function' && window.isAndroidApp && window.isAndroidApp()) {
      window.saveNativeFile(dataUrl, filename, mime);
    } else {
      const link = document.createElement('a');
      link.download = filename;
      link.href = dataUrl;
      link.click();
    }
  }

  /**
   * Exporta la Pizarra a PDF adaptado a su bounding box
   */
  static exportWhiteboardPdf(canvasEngine, title = 'Pizarra') {
    const { jsPDF } = window.jspdf;
    const bbox = canvasEngine.getBoundingBox();
    const margin = 40;

    const minX = Math.max(0, bbox.minX - margin);
    const minY = Math.max(0, bbox.minY - margin);
    const maxX = Math.min(canvasEngine.canvas.width, bbox.maxX + margin);
    const maxY = Math.min(canvasEngine.canvas.height, bbox.maxY + margin);

    const cropW = Math.max(120, maxX - minX);
    const cropH = Math.max(120, maxY - minY);

    const fullCanvas = document.createElement('canvas');
    fullCanvas.width = canvasEngine.canvas.width;
    fullCanvas.height = canvasEngine.canvas.height;
    const fCtx = fullCanvas.getContext('2d');

    fCtx.fillStyle = '#ffffff';
    fCtx.fillRect(0, 0, fullCanvas.width, fullCanvas.height);
    canvasEngine.renderBackground(fCtx);
    canvasEngine.renderImages(fCtx);

    fCtx.save();
    fCtx.globalCompositeOperation = 'multiply';
    for (const s of canvasEngine.strokes) {
      if (s.isHighlighter) canvasEngine.drawStroke(fCtx, s);
    }
    fCtx.restore();

    fCtx.save();
    for (const sh of canvasEngine.shapes) canvasEngine.drawShape(fCtx, sh);
    for (const s of canvasEngine.strokes) {
      if (!s.isHighlighter) canvasEngine.drawStroke(fCtx, s);
    }
    for (const t of canvasEngine.texts) canvasEngine.drawText(fCtx, t);
    fCtx.restore();

    const cropCanvas = document.createElement('canvas');
    cropCanvas.width = cropW;
    cropCanvas.height = cropH;
    const cCtx = cropCanvas.getContext('2d');
    cCtx.fillStyle = '#ffffff';
    cCtx.fillRect(0, 0, cropW, cropH);
    cCtx.drawImage(fullCanvas, minX, minY, cropW, cropH, 0, 0, cropW, cropH);

    const isLandscape = cropW >= cropH;
    const pdf = new jsPDF({
      orientation: isLandscape ? 'landscape' : 'portrait',
      unit: 'px',
      format: [cropW, cropH]
    });

    pdf.addImage(cropCanvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, cropW, cropH);
    const cleanTitle = (title || 'Pizarra').replace(/[^a-z0-9]/gi, '_').toLowerCase();
    const filename = `${cleanTitle}_${new Date().toISOString().slice(0, 10)}.pdf`;
    if (typeof window.saveNativeFile === 'function' && window.isAndroidApp && window.isAndroidApp()) {
      window.saveNativeFile(pdf.output('datauristring'), filename, 'application/pdf');
    } else {
      pdf.save(filename);
    }
  }

  /**
   * Exporta la página activa del lienzo como imagen PNG o JPG
   */
  static exportPageImage(canvasEngine, title = 'Documento', format = 'png') {
    const canvas = canvasEngine.canvas;
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = canvas.width;
    tempCanvas.height = canvas.height;
    const tCtx = tempCanvas.getContext('2d');

    tCtx.fillStyle = '#ffffff';
    tCtx.fillRect(0, 0, canvas.width, canvas.height);
    canvasEngine.renderBackground(tCtx);
    canvasEngine.renderImages(tCtx);

    tCtx.save();
    tCtx.globalCompositeOperation = 'multiply';
    for (const s of canvasEngine.strokes) {
      if (s.isHighlighter) canvasEngine.drawStroke(tCtx, s);
    }
    tCtx.restore();

    tCtx.save();
    for (const sh of canvasEngine.shapes) canvasEngine.drawShape(tCtx, sh);
    for (const s of canvasEngine.strokes) {
      if (!s.isHighlighter) canvasEngine.drawStroke(tCtx, s);
    }
    for (const t of canvasEngine.texts) canvasEngine.drawText(tCtx, t);
    tCtx.restore();

    const cleanTitle = (title || 'Documento').replace(/[^a-z0-9]/gi, '_').toLowerCase();
    const mime = format === 'jpeg' ? 'image/jpeg' : 'image/png';
    const ext = format === 'jpeg' ? 'jpg' : 'png';
    const filename = `${cleanTitle}_pagina_${new Date().toISOString().slice(0, 10)}.${ext}`;
    const dataUrl = tempCanvas.toDataURL(mime, 0.95);

    if (typeof window.saveNativeFile === 'function' && window.isAndroidApp && window.isAndroidApp()) {
      window.saveNativeFile(dataUrl, filename, mime);
    } else {
      const link = document.createElement('a');
      link.download = filename;
      link.href = dataUrl;
      link.click();
    }
  }

  /**
   * Renderiza el contenido de una página arbitraria a un contexto 2D
   */
  static renderPageDataToContext(ctx, page, width, height, canvasEngine) {
    ctx.clearRect(0, 0, width, height);

    if (page.isCover || page.template) {
      CoverDesigner.renderCover(ctx, width, height, page.coverData || page);
    } else {
      // Fondo blanco o tono de papel
      const bgColor = page.paperColor || '#ffffff';
      ctx.fillStyle = bgColor;
      ctx.fillRect(0, 0, width, height);

      // Patrón de fondo
      const pattern = page.backgroundPattern || 'grid';
      if (pattern === 'ruled') {
        ctx.strokeStyle = '#e2e8f0';
        ctx.lineWidth = 1;
        const lineGap = 28;
        const topMargin = 70;
        for (let y = topMargin; y < height; y += lineGap) {
          ctx.beginPath();
          ctx.moveTo(30, y);
          ctx.lineTo(width - 30, y);
          ctx.stroke();
        }
        ctx.strokeStyle = '#fecaca';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(76, 0);
        ctx.lineTo(76, height);
        ctx.stroke();
      } else if (pattern === 'grid') {
        ctx.strokeStyle = '#f1f5f9';
        ctx.lineWidth = 1;
        const gap = 20;
        for (let x = gap; x < width; x += gap) {
          ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, height); ctx.stroke();
        }
        for (let y = gap; y < height; y += gap) {
          ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(width, y); ctx.stroke();
        }
      } else if (pattern === 'dots') {
        ctx.fillStyle = '#cbd5e1';
        const gap = 24;
        for (let x = gap; x < width; x += gap) {
          for (let y = gap; y < height; y += gap) {
            ctx.beginPath(); ctx.arc(x, y, 1.25, 0, Math.PI * 2); ctx.fill();
          }
        }
      }
    }

    // Imágenes
    if (page.images) {
      for (const imgItem of page.images) {
        if (imgItem._element && imgItem._element.complete) {
          ctx.save();
          ctx.translate(imgItem.x + imgItem.width / 2, imgItem.y + imgItem.height / 2);
          if (imgItem.rotation) ctx.rotate(imgItem.rotation);
          ctx.drawImage(imgItem._element, -imgItem.width / 2, -imgItem.height / 2, imgItem.width, imgItem.height);
          ctx.restore();
        }
      }
    }

    // Subrayadores en modo multiply
    ctx.save();
    ctx.globalCompositeOperation = 'multiply';
    if (page.strokes) {
      for (const s of page.strokes) {
        if (s.isHighlighter) canvasEngine.drawStroke(ctx, s);
      }
    }
    ctx.restore();

    // Figuras y trazos
    ctx.save();
    if (page.shapes) {
      for (const sh of page.shapes) canvasEngine.drawShape(ctx, sh);
    }
    if (page.strokes) {
      for (const s of page.strokes) {
        if (!s.isHighlighter) canvasEngine.drawStroke(ctx, s);
      }
    }
    if (page.texts) {
      for (const t of page.texts) canvasEngine.drawText(ctx, t);
    }
    ctx.restore();
  }

  static escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str || '';
    return div.innerHTML;
  }
}


// === File: js/dashboard/contextMenu.js ===
// js/dashboard/contextMenu.js - Menú contextual de tres puntos para tarjetas
class ContextMenu {
  constructor(options = {}) {
    this.onOpen = options.onOpen || (() => {});
    this.onRename = options.onRename || (() => {});
    this.onMove = options.onMove || (() => {});
    this.onDuplicate = options.onDuplicate || (() => {});
    this.onExport = options.onExport || (() => {});
    this.onToggleFavorite = options.onToggleFavorite || (() => {});
    this.onDelete = options.onDelete || (() => {});
    this.onRestore = options.onRestore || (() => {});
    this.onPermanentDelete = options.onPermanentDelete || (() => {});

    this.menuEl = null;
    this.currentDoc = null;

    this.createMenu();
    this.bindGlobalEvents();
  }

  createMenu() {
    this.menuEl = document.createElement('div');
    this.menuEl.className = 'dashboard-context-menu hidden';
    document.body.appendChild(this.menuEl);
  }

  bindGlobalEvents() {
    document.addEventListener('pointerdown', (e) => {
      if (this.menuEl && !this.menuEl.contains(e.target) && !e.target.closest('.card-menu-btn')) {
        this.hide();
      }
    });

    window.addEventListener('scroll', () => this.hide(), true);
    window.addEventListener('resize', () => this.hide());
  }

  show(doc, triggerBtn) {
    this.currentDoc = doc;
    const isTrash = Boolean(doc.isTrash);

    if (isTrash) {
      this.menuEl.innerHTML = `
        <button class="ctx-item" id="ctxRestore">
          ${Icons.check} <span>Restaurar documento</span>
        </button>
        <div class="ctx-divider"></div>
        <button class="ctx-item danger" id="ctxPermDelete">
          ${Icons.trash} <span>Eliminar definitivamente</span>
        </button>
      `;

      this.menuEl.querySelector('#ctxRestore').addEventListener('click', () => {
        this.onRestore(this.currentDoc);
        this.hide();
      });

      this.menuEl.querySelector('#ctxPermDelete').addEventListener('click', () => {
        this.onPermanentDelete(this.currentDoc);
        this.hide();
      });
    } else {
      this.menuEl.innerHTML = `
        <button class="ctx-item" id="ctxOpen">
          ${Icons.edit} <span>Abrir</span>
        </button>
        <button class="ctx-item" id="ctxRename">
          ${Icons.edit} <span>Renombrar</span>
        </button>
        <button class="ctx-item" id="ctxFavorite">
          ${doc.isFavorite ? Icons.starFilled : Icons.star}
          <span>${doc.isFavorite ? 'Quitar de favoritos' : 'Añadir a favoritos'}</span>
        </button>
        <button class="ctx-item" id="ctxMove">
          ${Icons.folder} <span>Mover a carpeta...</span>
        </button>
        <button class="ctx-item" id="ctxDuplicate">
          ${Icons.copy} <span>Duplicar</span>
        </button>
        <button class="ctx-item" id="ctxExport">
          ${Icons.export} <span>Exportar (PDF/PNG)</span>
        </button>
        <div class="ctx-divider"></div>
        <button class="ctx-item danger" id="ctxDelete">
          ${Icons.trash} <span>Mover a la papelera</span>
        </button>
      `;

      this.menuEl.querySelector('#ctxOpen').addEventListener('click', () => {
        this.onOpen(this.currentDoc);
        this.hide();
      });

      this.menuEl.querySelector('#ctxRename').addEventListener('click', () => {
        this.onRename(this.currentDoc);
        this.hide();
      });

      this.menuEl.querySelector('#ctxFavorite').addEventListener('click', () => {
        this.onToggleFavorite(this.currentDoc);
        this.hide();
      });

      this.menuEl.querySelector('#ctxMove').addEventListener('click', () => {
        this.onMove(this.currentDoc);
        this.hide();
      });

      this.menuEl.querySelector('#ctxDuplicate').addEventListener('click', () => {
        this.onDuplicate(this.currentDoc);
        this.hide();
      });

      this.menuEl.querySelector('#ctxExport').addEventListener('click', () => {
        this.onExport(this.currentDoc);
        this.hide();
      });

      this.menuEl.querySelector('#ctxDelete').addEventListener('click', () => {
        this.onDelete(this.currentDoc);
        this.hide();
      });
    }

    const rect = triggerBtn.getBoundingClientRect();
    const menuWidth = 210;
    let left = rect.right - menuWidth;
    let top = rect.bottom + 6;

    // Evitar desbordamiento de pantalla
    if (left < 10) left = 10;
    if (top + 280 > window.innerHeight) {
      top = rect.top - 270;
    }

    this.menuEl.style.left = `${left}px`;
    this.menuEl.style.top = `${top}px`;
    this.menuEl.classList.remove('hidden');
  }

  hide() {
    if (this.menuEl) {
      this.menuEl.classList.add('hidden');
    }
  }
}



